/* All content is local. Edit this file to change slide text and presenter notes. */
window.SOURCES={
 T1:{title:'Tata Medical Center / AMRI Hospital case study',detail:'Uploaded study, February 2023. Plans: pp. 16–18. Environmental section: p. 23. Photographs: pp. 37–38. Student authors: Kriti Gupta, Muskan Jindal, Poulami Jana, Rajarshi Biswas, Rashmita Bhowmik and Rinzing Ongmu Bhutia.',file:'631861548-TATA-MEDICAL-AMRI-CENTER-CASR-STUDY.pdf'},
 T2:{title:'Tata Medical Centre architectural study sheets',detail:'Uploaded thesis study by B. Pratishtha, CSI Institute of Technology, guided by Ar. Sita. Tata material: sheets A1–A5 only. Departmental plan images supply the geometric base. Some narrative statistics concern a different reporting date and are not used as plan capacities.',file:'631096676-case-study-sheets-18031aa007-pdf.pdf'},
 T3:{title:'CannonDesign · Tata Medical Center',url:'https://www.cannondesign.com/work/tata-medical-center',detail:'Architect’s account of the public/private sequence, courtyards, sandstone, seasonal wind orientation, rainwater storage and selected naturally ventilated waiting areas. The 150-bed figure is identified as the architect’s design brief, not a current operating count.'},
 T4:{title:'Tata Medical Center · A Glorious Decade',url:'https://tmckolkata.com/services/TMC_A_Glorious_Decade.pdf',detail:'Official hospital publication. Confirms the 13-acre campus and opening on 16 May 2011. Published opening capacities vary, so the deck qualifies its capacity as a design brief.'},
 M1:{title:'MVR Cancer Hospital · Live Case Study, ADFT VII',detail:'Uploaded A1 sheets 01–10. Authors: Nilesh Khade, Ann Varghese, Mandar Gambhir, Faizan Mulla, Aathinadh Chandra, Sachin Kethavath, Dubori Sonowal and Reethika Rajeev. Site: 01. Lower Ground: 02. Ground: 03–04. First: 05. Second: 06. Third: 07. Fourth: 08. Fifth: 09. Sixth/Seventh: 10.',file:'COMMERCE OF CHAMBER SORAN_STRUCTURE 28 6 2026.pdf'},
 M2:{title:'MVR Cancer Centre · Spatial & Plan Analysis',detail:'Uploaded restructured presentation. Site entrances: pp. 2–4. Floor interpretations: pp. 5–22. Ground circulation: p. 23. Where a secondary label differs from a readable room label in the A1 drawing, the A1 drawing takes priority.',file:'MVR_Cancer_Centre_Yasr_Restructured_Final_v4.pptx.pdf'},
 M3:{title:'Nalapat Architects · Cancer Center, Calicut',url:'https://www.nalapatarchitects.com/healthcare-projects/healthcare_all?id=63&pid=2&status=2',detail:'Architect’s concept: separate functional forms, planted spaces between them, connecting bridges, wind, sun, greenery and water. The architect’s publication lists 15 acres, 500,000 ft² and 400 beds. Those design-publication figures differ from the operating and study figures.'},
 M4:{title:'CARE Foundation · Hospital & Research Centre',url:'https://www.carecalicut.org/our-projects/',detail:'Owner’s account: Chathamangalam near NIT Kozhikode, 15.5-acre site, operational in 2017. The uploaded survey rounds the campus to 15 acres.'},
 M5:{title:'CARE Foundation · MVR opening announcement',url:'https://www.carecalicut.org/mediacenter/mvr-cancer-center-inaguration-in-mathrubhumi-news-paper/',detail:'Owner’s opening announcement records 300 beds and 600,000 ft², equivalent to approximately 55,742 m². The deck uses this published study-era capacity, not a claim about the current hospital.'},
 M6:{title:'MVR Cancer Centre · Facilities',url:'https://www.mvrcancerhospital.com/our_services/facilities-2/',detail:'Official surgical facilities page confirms eight operating theatres, a cath lab, pre/post-operative areas, naturally lit induction space and associated support.'},
 M7:{title:'MVR Cancer Centre · About Us / Facilities',url:'https://www.mvrcancerhospital.com/about-us/',detail:'Current official description confirms the green campus and comprehensive oncology services. Current campus figures (17 acres, 600,000 ft²) and 12 BMT units differ from the older drawing set, which labels 11 BMT rooms.'},
 P1:{title:'Supplied architectural and clinical photographs',detail:'Tata photographs/sketch/elevations and MVR renderings/clinical photographs supplied in case studies(1).zip. Concept renderings are labelled as renderings, not presented as as-built photographs. Copyright remains with the original photographers/designers.'},
 B1:{title:'Comprehensive Cancer Hospital · Space Program',detail:'Uploaded Architecture Design 7 brief. Used only for the short introduction and broad functional vocabulary, without importing the proposed project’s room counts into either precedent.',file:'Space Program_Comprehensive Cancer Hospital(1).docx'}
};
const sl=(type,title,sub,props={})=>({type,title,sub,...props});
window.SLIDES=[
 sl('cover','Comprehensive\nCancer Hospitals','Architectural case studies',{chapter:'Architecture Design 7',sources:['T3','M3','P1'],notes:'Present the two buildings as architectural precedents. Tata Medical Center is examined through the selected original building drawings. MVR is examined through the complete Lower Ground to Seventh Floor set. The comparison concentrates on access, departmental zoning, circulation, clinical relationships and the healing environment.'}),
 sl('intro','A connected system of care','Comprehensive cancer hospital',{chapter:'Introduction',sources:['B1'],notes:'A comprehensive cancer hospital combines diagnosis, multiple treatment modalities, inpatient care and support. The diagram is a functional framework, not a universal patient itinerary. A person may return repeatedly to outpatient care and treatment, while other patients need surgery, critical care or protected inpatient accommodation. Service flows support every department. The two precedents show how architecture organizes this complexity.'}),
 sl('profile','Tata Medical Center','New Town, Kolkata, West Bengal, India',{chapter:'Tata Medical Center',photo:'photos/tata-01.webp',caption:'Arrival court and sandstone façade · supplied photograph',facts:[['Architect','CannonDesign'],['Opened','16 May 2011'],['Campus','13 acres ≈ 5.26 ha'],['Design brief','Approximately 150 beds']],statement:'Clinical buildings and administrative wings frame a sequence of open courts.',sources:['T1','T2','T3','T4','P1'],notes:'The hospital opened on 16 May 2011 according to the official anniversary publication. The 13-acre figure refers to the hospital campus. Approximately 150 beds is the architect’s stated design brief. Published operational bed counts vary and should not be conflated with the selected architectural drawings. The site sits in New Town, with urban road frontage and a water edge recorded in the supplied context material.'}),
 sl('concept','A hospital organized around courtyards','Concept and design philosophy',{chapter:'Tata Medical Center',photo:'photos/tata-05.webp',caption:'Courtyard, covered edge and connecting bridge',headline:'A healing campus',points:[['Human scale','Separate wings reduce the apparent size of the hospital.'],['Public to private','Courts and connecting passages mediate clinical access.'],['Family presence','Waiting areas and outdoor edges accommodate accompanying relatives.']],sources:['T2','T3','P1'],notes:'CannonDesign describes a campus experience formed by courtyards and outdoor hallways. The photograph shows a planted court and a bridge between wings. Read the open space as part of the circulation sequence and as a place to pause. The shaded edges and visible landscape offer spatial orientation. The planning separates departments while preserving connections, rather than relying on a single deep floor plate.'}),
 sl('massing','Connected wings, open centre','Form, massing and functional organization',{chapter:'Tata Medical Center',hospital:'tata',points:[['Clinical wing','Outpatient care and day treatment occupy the principal arrival side.'],['Treatment wing','Imaging and technical treatment form a controlled cluster.'],['Administration','A narrower parallel wing faces the central court.'],['Support','Service volumes occupy the rear of the composition.']],sources:['T1','T2'],notes:'The diagram traces the principal footprints visible in the ground-floor source. The axonometric height is schematic and does not claim measured storey heights. It explains the relationship between the main clinical wing, treatment wing, administration and support. The central void remains open and the wings connect at selected points. Refer to the floor slides for the actual internal walls and rooms.'}),
 sl('site','Entrances and arrival sequence','Site access and building thresholds',{chapter:'Tata Medical Center',hospital:'tata',mode:'entries',points:[['01 · Main/public','Arrival gate, drop-off and lobby/counselling access.'],['02 · Therapy arrival','A secondary approach serves the treatment side.'],['03 · Mortuary/service','Rear support access avoids the main waiting front.'],['Emergency and staff','Functional approaches shown as inferred access zones.']],sources:['T1','T2'],notes:'The Tata study identifies main entry, radiation-therapy arrival and mortuary arrival. The selected plan establishes the public lobby and rear support locations. The schematic shows their relationships, not surveyed gate coordinates. The uploaded drawings do not reliably identify every separate staff or emergency door within this building. Hollow markers therefore identify functional access zones only. Main entry and treatment arrival should not be confused with an emergency-only entrance.'}),
 sl('site','Public arrival and rear support','External circulation and site zoning',{chapter:'Tata Medical Center',hospital:'tata',mode:'routes',points:[['Visitor movement','Drop-off leads directly to the public clinical edge.'],['Pedestrian approach','Covered connections link waiting, administration and the courts.'],['Service movement','Rear support access connects to technical and supply functions.'],['Landscape structure','The central court organizes the wings and clarifies orientation.']],sources:['T1','T2'],notes:'External paths are analytical connections between documented destinations. They do not establish one-way traffic regulations or exact access-control operation. Visitor and treatment flows meet the public clinical zones, while service destinations occupy the rear. The court creates a strong orientation feature, but multiple wings also require consistent signs. Staff can use more than one shared circulation segment; separate colored routes do not imply separate corridors throughout.'}),
 sl('floor','Basement','Radiotherapy and technical support',{chapter:'Tata Medical Center',plans:['tata-basement'],points:[['Treatment edge','Waiting, planning, brachytherapy and shielded treatment rooms.'],['Support belt','Laundry, linen, CSSD, changing and technical rooms.'],['Vertical link','Lift and stair groups connect clinical and service levels.']],detail:'cssd',sources:['T1'],notes:'Source: Tata/AMRI study, page 16, photographed basement evacuation plan. Readable labels include laundry, soiled linen, CSSD cleaning and packing, sterile storage, AHU for CSSD, lockers, waiting, therapy planning, brachytherapy, tomotherapy, Radixact and LINAC. The original raster is limited in resolution. Broad zoning preserves the documented layout. CSSD arrows express a conceptual dirty-to-clean workflow; they do not certify operational pressure regimes or every door assignment.'}),
 sl('floor','Ground floor','Public access, outpatient care and diagnostics',{chapter:'Tata Medical Center',plans:['tata-ground'],points:[['Arrival front','Lobby, counselling and OPD form the public clinical wing.'],['Treatment cluster','Imaging and radiation occupy the rear clinical block.'],['Administrative edge','Separate offices face the courtyard and connect through shared circulation.']],detail:'privacy',sources:['T1','T2'],notes:'Sources: Tata study sheet A3 and Tata/AMRI page 17. The numbered source legend distinguishes lobby/counselling/OPD, imaging/radiation therapy, academic/administration and service support. Arrows follow the principal visible connecting paths. The source is a departmental plan rather than a fully legible room schedule, so exact clinic counts and every internal staff-only door are not asserted. Privacy increases from lobby and waiting to consultation and controlled treatment.'}),
 sl('floor','First floor','Day hospital, inpatient care and laboratories',{chapter:'Tata Medical Center',plans:['tata-first'],points:[['Day hospital','Repeated treatment spaces occupy the long clinical wing.'],['Inpatient unit','A distinct block separates staying patients from day visits.'],['Laboratory link','Clinical laboratories connect across the rear bridge.']],detail:'daycare',sources:['T1','T2'],notes:'Sources: Tata sheet A4 and Tata/AMRI page 18. The plan legend identifies day hospital, inpatient unit, academic/administration and clinical laboratories. The day hospital’s repeated bays support supervised treatment. The inpatient block has a more enclosed central arrangement with rooms around its perimeter. The laboratory bridge creates a direct connection at this level. Colored patient, staff and support arrows are interpretations of the visible circulation network, not proof of fully segregated paths.'}),
 sl('floor','Second floor','Surgery, critical care and recovery',{chapter:'Tata Medical Center',plans:['tata-second'],points:[['Restricted clinical wing','Invasive services and surgical care occupy the long block.'],['Critical adjacency','ICU, high-dependency care and recovery sit in the connected rear block.'],['Controlled thresholds','Lift arrivals require a clear transition into clinical areas.']],detail:'surgery',sources:['T1','T2'],notes:'Sources: Tata sheet A5 and Tata/AMRI page 18. The source legend names invasive services/surgical care, ICU/high dependency/recovery and academic/administration. The arrangement supports short links between surgery and critical care at the same level. The clean-supply and dirty-return inset is a workflow schematic. The uploaded raster does not establish a complete dedicated dirty corridor, so no such corridor is claimed as a documented feature.'}),
 sl('stack','Vertical zoning','Clinical intensity and vertical connections',{chapter:'Tata Medical Center',hospital:'tata',points:[['Ground','Public reception and outpatient access.'],['First','Day hospital, inpatient accommodation and laboratories.'],['Second','Surgery and critical care share a controlled level.'],['Basement','Treatment and technical support connect through cores.']],sources:['T1','T2'],notes:'The stack includes exactly the four supplied floor plans used in this case study. It is an exploded analytical diagram, not a measured section. The floor relationships are supported by the source legends. Tata’s source does not consistently identify lift types, so lift symbols are described as cores without assigning all of them as patient-only, visitor-only or service-only. Public, clinical and service connections represent functional networks.'}),
 sl('network','Departmental relationships','Internal circulation and privacy gradient',{chapter:'Tata Medical Center',hospital:'tata',sources:['T1','T2'],notes:'This adjacency diagram synthesizes the supplied plans. Outpatients move from reception toward consultation, diagnostics and treatment. Inpatients connect with day treatment and critical care through the clinical cores. Surgery has a same-level relationship with critical care in the selected drawings. CSSD and other support require controlled vertical connections. The diagram illustrates functional relationships and privacy, not a measured distance or a claim that every route has its own corridor.'}),
 sl('environment','Light, shade and sheltered movement','Environmental strategy and healing architecture',{chapter:'Tata Medical Center',hospital:'tata',photo:'photos/tata-facade.webp',points:[['Courtyards','Openings and shaded edges connect circulation with the outdoors.'],['Façade protection','Recesses, horizontal shading and durable sandstone respond to heat and rain.'],['Water and air','Rainwater storage supports irrigation; selected waiting areas can use operable windows.']],sources:['T2','T3','P1'],notes:'CannonDesign describes orientation toward changing seasonal winds, openings through the building mass and underground rainwater storage for garden irrigation. It also states that the complex is air-conditioned, with mechanical provision for operable windows in certain waiting areas. This should not be interpreted as natural ventilation for operating theatres, isolation rooms or all clinical spaces. The illustrated environmental section is from the uploaded source and is conceptual rather than a verified ventilation simulation.'}),
 sl('evaluation','Architectural strengths and limitations','Tata Medical Center',{chapter:'Tata Medical Center',photo:'photos/tata-atrium.webp',strengths:[['Courtyard identity','Landscape helps patients read the campus.'],['Human scale','Linked wings create smaller, recognizable destinations.'],['Clinical relationships','Day care, laboratories, surgery and critical care form legible clusters.']],limits:[['Travel distance','Connections across several wings increase walking.'],['Wayfinding','A clear hierarchy of signs is necessary at bridges and junctions.'],['Technical enclosure','Shielded and controlled departments cannot rely on open-air planning.']],lesson:'Landscape is most useful when it also organizes movement.',sources:['T1','T2','T3','P1'],notes:'Strengths and limitations are architectural interpretations of the drawings and photographs. Courtyards and bridges create orientation opportunities, but the same dispersed composition can lengthen travel. The design lesson is to integrate landscape with circulation rather than treating it as leftover space. The evaluation does not claim measured travel-time performance, energy savings or patient outcome data.'}),
 sl('profile','MVR Cancer Centre','Chathamangalam, Kozhikode, Kerala, India',{chapter:'MVR Cancer Centre',photo:'photos/mvr-13.webp',caption:'MVR entrance · supplied architectural rendering',facts:[['Architect','Nalapat Architects'],['Operational','2017'],['Study-era capacity','300 beds'],['Published built area','≈55,742 m²']],statement:'A linear clinical block and lower curved wing connect around landscaped spaces.',sources:['M1','M3','M4','M5'],notes:'The owner’s opening announcement supports 300 beds and 600,000 square feet (approximately 55,742 square metres). The supplied study uses those figures and rounds the campus to 15 acres; CARE Foundation gives 15.5 acres. The architect’s design publication gives 400 beds and 500,000 square feet, while the current hospital describes a 17-acre campus. These are different publication scopes, not interchangeable measurements. This presentation analyzes the supplied drawing set.'}),
 sl('concept','Nature between clinical blocks','Concept and design philosophy',{chapter:'MVR Cancer Centre',photo:'photos/mvr-19.webp',caption:'Courtyard and bridge · supplied architectural rendering',headline:'Connection to the outside',points:[['Separate forms','Functional volumes create landscaped spaces between them.'],['Bridges','Connections across the courts retain visual contact with the exterior.'],['Healing setting','Greenery and water soften the experience of a large specialist hospital.']],sources:['M3','P1'],notes:'Nalapat Architects describes life-affirming spaces using sun, wind, greenery and water. The program separates functions into built forms connected by bridges, leaving planted spaces between them. The image is a design rendering from the supplied package. It expresses the architectural intent and is not a photograph of completed construction. Technical clinical areas still need their own controlled environmental systems.'}),
 sl('massing','A spine with connected branches','Form, massing and functional organization',{chapter:'MVR Cancer Centre',hospital:'mvr',points:[['Block B','The long inpatient and emergency volume forms the principal spine.'],['Block A','A lower curved block accommodates clinical and public functions.'],['OPD','The outpatient end addresses the principal arrival.'],['Support blocks','Canteen/MEP and service volumes connect near the pond.']],sources:['M1','M2','M3'],notes:'The source site drawing names Block B, Block A, OPD, canteen/MEP and service block. The axonometric diagram uses those footprints and schematic relative height. It does not reproduce a surveyed structural model. The form balances a long repetitive clinical bar with a curved lower block and distinct support buildings. The connected outdoor gaps increase façade exposure but create several orientation decisions for visitors.'}),
 sl('site','Entrances and arrival sequence','Public, emergency, staff and service access',{chapter:'MVR Cancer Centre',hospital:'mvr',mode:'entries',points:[['01 · Main/OPD','Visitor parking and drop-off connect to the outpatient approach.'],['02 · Emergency','Separate arrival reaches the rear edge of Block B.'],['03–04 · Service','Canteen/MEP and service-block entries serve the southern edge.'],['Staff access','Staff parking lies along the east boundary; the exact staff door is not labelled.']],sources:['M1','M2'],notes:'Sources: MVR A1 sheet 01 and the restructured deck, pages 2–4. Main/OPD, emergency, canteen/MEP service and service-block entrances are identified in the provided annotations. Staff parking is documented; a distinct staff-only external door is not reliably located, so staff approach is shown as an inferred connection. The site arrival and ground-floor main entrance occur at different points in the approach sequence. The ground plan shows the approach continuing along the eastern connection.'}),
 sl('site','Two external movement systems','Site zoning and circulation',{chapter:'MVR Cancer Centre',hospital:'mvr',mode:'routes',points:[['Public approach','Visitor parking feeds the OPD arrival and pedestrian connection.'],['Emergency approach','The rear clinical edge provides a separate destination.'],['Service edge','The perimeter route reaches loading and technical blocks.'],['Landscape buffer','The pond and planted gaps separate the major volumes.']],sources:['M1','M2'],notes:'The source site diagram distinguishes a visitor/emergency route along the rear edge and a service route along the outer perimeter. The animated overlay indicates destinations rather than traffic regulations. Emergency and visitor vehicles may still share parts of the external access road. The architectural value comes from separate arrival points and keeping service destinations away from principal waiting areas. No traffic capacity or turning-radius compliance is claimed.'}),
 sl('floor','Lower ground floor','Radiation treatment and support connections',{chapter:'MVR Cancer Centre',plans:['mvr-lower'],points:[['Shielded treatment','LINAC rooms and their maze/console interfaces form a technical cluster.'],['Clinical approach','The curved circulation spine reaches treatment preparation and support.'],['Separate support','Canteen and technical blocks connect across external gaps.']],detail:'radiation',sources:['M1','M2'],notes:'Source: MVR A1 sheet 02. The plan clearly shows radiation bunkers and adjacent control/support rooms. The source’s thick-wall observations are not used as construction specifications because they vary within the sheet and require specialist shielding calculations. The diagram highlights reception, preparation, controlled access and the maze relationship. Routine external-beam treatment does not require a universal recovery step; any observation need depends on the procedure. The circulating staff/technical route is analytical.'}),
 sl('floor','Ground floor','OPD, emergency and public clinical access',{chapter:'MVR Cancer Centre',plans:['mvr-ground'],points:[['Outpatient module','Repeated consultation and procedure rooms flank a principal corridor.'],['Emergency threshold','A separate entry reaches triage, examination and observation.'],['Shared junctions','Imaging, pharmacy and vertical cores need clear signs and controlled transfers.']],detail:'opd',sources:['M1','M2'],notes:'Sources: MVR A1 sheets 03–04 and restructured page 23. The study reports 27 consultation rooms, five pre-assessment rooms and five procedure rooms, with some planned rooms converted into waiting. These are survey observations rather than a certified current room count. The emergency detail notes that there is no separate lift service directly between emergency and the OT complex. Therefore the deck does not claim a dedicated emergency lift. The main circulation connects OPD with the curved clinical block.'}),
 sl('floor','First floor','Diagnostics, endoscopy and sterile supply',{chapter:'MVR Cancer Centre',plans:['mvr-first'],points:[['Diagnostic cluster','Blood bank, hematology and endoscopy group near the clinical cores.'],['CSSD','Decontamination, packing and sterile storage define a controlled sequence.'],['Academic branch','Administrative and meeting spaces occupy the lower curved block.']],detail:'cssd',sources:['M1','M2'],notes:'Source: MVR A1 sheet 05. Blood-bank labels distinguish donor reception and refreshment from laboratory processing and soiled holding. Endoscopy includes preparation/recovery, scope washing and storage. CSSD labels include decontamination, trolley wash, packing and sterile storage. The source records potential movement conflicts on this mixed-service floor; its criticism should be read as a study inference, not a proven infection-control failure. CSSD sits below the surgical level, making controlled vertical transport important.'}),
 sl('floor','Second floor','Surgery and chemotherapy',{chapter:'MVR Cancer Centre',plans:['mvr-second'],points:[['Eight operating theatres','The surgical cluster includes pre-op, induction, recovery and support.'],['Clean and dirty routes','The source marks a rear dirty corridor and controlled patient/staff thresholds.'],['Day treatment','Infusion wards and paediatric infusion occupy the eastern wing.']],detail:'ot',sources:['M1','M6'],notes:'Source: MVR A1 sheet 06, supported by the official surgical facilities page. Eight OTs and a cath lab appear in the source material. The study distinguishes sterile, clean and dirty areas, staff changing, the patient lift lobby and pre/post-operative spaces. The overlay follows the visible central clean corridor and peripheral dirty-return arrangement schematically. Infusion has nurse stations, drug mixing, soiled support and separate paediatric waiting. The deck does not assert regulatory compliance from the study’s bed ratios.'}),
 sl('floor','Third floor','Critical care and inpatient accommodation',{chapter:'MVR Cancer Centre',plans:['mvr-third'],points:[['Critical care cluster','ICU, PICU and HDU/dialysis occupy the western side.'],['Ward sequence','Standard rooms extend along the eastern corridor.'],['Core relationship','Patient transport links critical care with surgery below.']],detail:'ward',sources:['M1','M2'],notes:'Source: MVR A1 sheet 07. The drawing labels ICU, PICU and HDU/dialysis around nursing and utility spaces. The eastern side has standard inpatient rooms and suites. Core positions create the vertical relationship with the surgical level, but the actual lift operations and transfer protocols are not established by the plan. Distributed nursing functions support observation; long corridors remain a travel-distance consideration. Fire stairs are shown, without inferring unverified fire compartments.'}),
 sl('paired','Fourth and fifth floors','Specialized care within the inpatient stack',{chapter:'MVR Cancer Centre',plans:['mvr-fourth','mvr-fifth'],planLabels:['04 · Wards, laboratories and nuclear medicine','05 · Standard rooms and distributed support'],points:[['Fourth floor','Controlled nuclear-medicine rooms and laboratories coexist with ordinary wards.'],['Fifth floor','Repeated perimeter rooms share the spine and nursing/support nodes.'],['Circulation','Patient/visitor and service movements meet at identifiable core junctions.']],sources:['M1','M2'],notes:'Sources: MVR A1 sheets 08–09. The fourth-floor drawing labels molecular laboratory, microbiology, nuclear medicine, dose administration, isolation, biomedical support and ward rooms. The fifth is predominantly standard inpatient rooms and a suite. The study reports 27 standard rooms and one suite on the fourth, and 41 standard rooms and one suite on the fifth. The source labels multiple nurse stations, service lifts, patient lifts, visitor lifts and end fire stairs. Route colors do not imply that all ward corridors are dedicated to one user group.'}),
 sl('paired','Sixth and seventh floors','Accommodation hierarchy and protected BMT care',{chapter:'MVR Cancer Centre',plans:['mvr-sixth','mvr-seventh'],planLabels:['06 · Shared wards, double rooms and standard rooms','07 · BMT, deluxe rooms, standard rooms and suites'],points:[['Sixth floor','Different room types share a long corridor and distributed support.'],['Seventh floor','The BMT wing has room airlocks and a controlled internal threshold.'],['Protected support','Clean utility, sterile storage, soiled hold and staff changing support the BMT sequence.']],sources:['M1','M2','M7'],notes:'Source: MVR A1 sheet 10. The sixth-floor study records eight five-bed wards, 11 double rooms and 14 standard rooms. The seventh-floor drawing labels seven BMT rooms in one row and four in the other, totaling 11. Current hospital literature lists 12 BMT units; the deck follows the supplied plan rather than merging the counts. BMT airlocks, staff changing, clean utility, sterile store and soiled holding are visible. Air pressure values and complete clean/dirty operational separation are not verified by these drawings.'}),
 sl('stack','The complete clinical stack','Vertical zoning and specialized circulation',{chapter:'MVR Cancer Centre',hospital:'mvr',points:[['Treatment base','Radiation sits at Lower Ground; OPD and emergency at Ground.'],['Technical middle','Diagnostics/CSSD, surgery and critical care occupy successive levels.'],['Inpatient upper levels','Wards and specialized accommodation culminate in BMT.']],sources:['M1','M2','M6'],notes:'This exploded stack includes all nine documented MVR levels. The floor plates are images of the source drawings, not invented plans. The schematic spine indicates visitor/patient and support vertical connections, without claiming every lift serves every department in the same way. The detailed workflows shown in the interactive panel explain radiation access, OT clean/dirty movement and BMT thresholds. Open individual floor plates to inspect the drawn cores and rooms.'}),
 sl('environment','Landscape, daylight and clinical efficiency','Environmental strategy, strengths and limitations',{chapter:'MVR Cancer Centre',hospital:'mvr',photo:'photos/mvr-20.webp',points:[['Daylight and views','Perimeter patient rooms look outward from the linear ward blocks.'],['Landscape connection','Pond, planted gaps and bridges connect clinical movement with the exterior.'],['Planning trade-off','Clear stacking and technical clusters coexist with long corridors and complex junctions.']],sources:['M1','M3','M7','P1'],notes:'The supplied plans place many patient rooms along external walls, offering daylight and views. The architect describes a landscape strategy using greenery, water and linked courtyards. These are qualitative architectural observations, not measured daylight or energy performance. Long ward corridors increase potential walking distances. Mixed specialized departments on some levels make signs, access control and vertical service transport important. Natural ventilation should not be assumed for protected BMT, operating rooms or every clinical area.'}),
 sl('comparison','Two approaches to a healing hospital','Comparative analysis and design lessons',{chapter:'Synthesis',sources:['T1','T2','T3','M1','M3'],notes:'Tata’s strongest spatial lesson is the courtyard campus: smaller linked wings and a gradual public-to-private transition. MVR’s strongest organizational lesson is the explicit vertical stack with a long spine, specialized departments and separate support blocks. Both depend on clear entrances, controlled clinical thresholds and reliable service movement. For a new design, prioritize short critical-care relationships, daylight and views for suitable patient areas, legible wayfinding, and protected treatment environments. Neither precedent should be copied without climate, program and operational adaptation.'})
];


/* ===== app.js ===== */
'use strict';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const requestedSlide=Number(location.hash.slice(1))||1;
let current=Math.min(SLIDES.length-1,Math.max(0,(Number(location.hash.slice(1))||1)-1)),motion=!matchMedia('(prefers-reduced-motion: reduce)').matches;
const tata=['tata-basement','tata-ground','tata-first','tata-second'],mvr=['mvr-lower','mvr-ground','mvr-first','mvr-second','mvr-third','mvr-fourth','mvr-fifth','mvr-sixth','mvr-seventh'];
const points=a=>`<div class="points">${(a||[]).map(([a,b])=>`<div class="point"><b>${esc(a)}</b><p>${esc(b)}</p></div>`).join('')}</div>`;
const photo=(path,caption='')=>`<div class="photowrap" data-photo="${esc(path)}"><img class="photo" src="${esc(path)}" alt="${esc(caption)}">${caption?`<div class="caption">${esc(caption)}</div>`:''}</div>`;
function planSVG(id){const p=PLANS[id];return `<svg viewBox="0 0 1000 ${p.vbHeight}" role="img" aria-label="${esc(p.hospital+' '+p.label+' floor plan with analytical zoning and circulation')}"><image href="${p.path}" width="1000" height="${p.vbHeight}"/><g class="zones">${Object.entries(p.zones||{}).map(([k,d])=>`<path class="zone" d="${d}" fill="${ZONES[k]?.[1]||'#999'}"/>`).join('')}</g><g class="flows">${(p.routes||[]).map(r=>`<path class="route" d="${r.d}" stroke="${FLOWS[r.kind][1]}"><title>${esc(r.label)}</title></path>`).join('')}</g><g class="pins">${(p.pins||[]).map(a=>`<g class="pin ${a.kind}" transform="translate(${a.x} ${a.y})"><title>${esc(a.text)}</title><circle r="13"/><text>${esc(a.label)}</text></g>`).join('')}</g></svg>`}
function legend(id){const p=PLANS[id];return `<div class="legend">${Object.keys(p.zones||{}).filter(k=>ZONES[k]).map(k=>`<span><i style="background:${ZONES[k][1]}"></i>${ZONES[k][0]}</span>`).join('')}${[...new Set((p.routes||[]).map(r=>r.kind))].map(k=>`<span><i style="background:${FLOWS[k][1]};height:3px"></i>${FLOWS[k][0]}</span>`).join('')}</div>`}
function layerbar(){return `<div class="layerbar">${['Zones','Flows','Pins','Source'].map(v=>`<button data-layer="${v.toLowerCase()}" class="${v==='Source'?'':'on'}">${v}</button>`).join('')}</div>`}
function plan(id,title=''){return `<div class="planarea" data-planarea="${id}">${title?`<h3>${esc(title)}</h3>`:''}${layerbar()}<div class="planframe" data-plan="${id}">${planSVG(id)}<span class="hint">Click to inspect + zoom</span></div>${legend(id)}<div class="planmeta"><span>Source: ${esc(PLANS[id].source)}</span><span>Analytical circulation · not to scale</span></div></div>`}
const details={radiation:'mvr-linac-sketch.webp',opd:'mvr-opd.webp',cssd:'mvr-cssd.webp',ot:'mvr-ot.webp',ward:'mvr-icu.webp'};
const workflows={cssd:['Sterile supply · conceptual sequence','Soiled receipt → Wash → Pack → Sterilize → Sterile storage'],privacy:['Access gradient','Public → Consultation → Controlled treatment → Restricted care'],daycare:['Day treatment · functional sequence','Arrival → Assessment → Infusion → Observation'],surgery:['Same-level clinical relationship','Surgery ↔ Recovery ↔ Critical care'],radiation:['Radiotherapy · access sequence','Reception → Preparation → Controlled maze → Treatment'],opd:['Outpatient and emergency','Registration → Waiting → Consultation<br>Emergency → Triage → Observation'],ot:['Surgical circulation','Patient → Pre-op → OT → Recovery<br>Clean supply ⇢ OT ⇢ Dirty return'],ward:['Inpatient relationships','Patient core ↔ Nursing ↔ Rooms<br>Service core ↔ Utility / support']};
function workflow(k){const a=workflows[k];return a?`<div class="miniworkflow"><small>${a[0]}</small><div>${a[1]}</div></div>`:''}
function network(intro=false){const nodes=intro?[[100,120,'Arrival / OPD'],[440,120,'Diagnosis'],[790,120,'Treatment'],[790,350,'Inpatient care'],[440,350,'Recovery / follow-up'],[100,350,'Clinical support']]:[[100,110,'Reception / OPD'],[440,110,'Diagnostics'],[790,110,'Day treatment'],[790,350,'Inpatient care'],[440,350,'Surgery / ICU'],[100,350,'CSSD / support']];return `<svg class="diagram" viewBox="0 0 1120 550"><defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10" fill="#8d9d85"/></marker></defs><path d="M320 160H440 M660 160H790 M900 210V350 M790 400H660 M440 400H320 M210 350V210 M550 210V350" fill="none" stroke="#8d9d85" stroke-width="3"/><path class="route" d="M320 160H440 M660 160H790 M900 210V350" stroke="#248c83"/>${nodes.map(([x,y,t],i)=>`<g transform="translate(${x} ${y})"><rect width="220" height="100" fill="${i<2?'#dedbbf':i<4?'#c2d6c8':'#d6cec3'}"/><text x="110" y="55" text-anchor="middle" font-size="23">${t}</text></g>`).join('')}<text x="100" y="515" font-size="18">Functional relationships • routes vary with diagnosis and treatment</text></svg>`}
function massing(h){const isT=h==='tata';const blocks=isT?[[120,140,140,360,55,'Administration','#9684ac'],[440,180,170,390,80,'Clinical wing','#d1a55d'],[450,35,350,110,60,'Treatment','#ae7196'],[120,30,260,80,35,'Support','#949da0']]:[[130,110,680,120,130,'Block B · clinical spine','#759d8b'],[160,380,510,105,50,'Block A · clinical / public','#c7a56a'],[790,180,115,200,55,'OPD','#d5b775'],[80,500,250,80,30,'Service / MEP','#949da0']];return `<svg class="diagram" viewBox="0 0 1000 670"><g transform="translate(30 35) skewY(-8)"><path d="M65 20H930V620H65Z" fill="#e4e5d8"/><path d="M330 290H710V430H330Z" fill="#bbceb0"/>${blocks.map(([x,y,w,h,z,t,c])=>`<g><path d="M${x} ${y}h${w}v${h}h-${w}Z" fill="${c}"/><path d="M${x} ${y+h}l30 ${z}h${w}l-30 -${z}Z" fill="${c}" opacity=".65"/><path d="M${x+w} ${y}l30 ${z}v${h}l-30 -${z}Z" fill="${c}" opacity=".45"/><text x="${x+12}" y="${y+40}" font-size="21">${t}</text></g>`).join('')}<text x="360" y="350" font-size="24">${isT?'Open courtyard':'Planted spaces'}</text></g><text x="75" y="655" font-size="17">Analytical massing • footprints simplified • heights schematic</text></svg>`}
function body(s){switch(s.type){case'intro':return `<div class="split"><div>${network(true)}</div><div class="points"><h2>Architecture connects a complex journey.</h2>${points([['Diagnosis','Outpatient assessment, imaging and laboratory services.'],['Treatment','Radiotherapy, systemic therapy, surgery and critical care.'],['Support','Inpatient care, rehabilitation, sterile supply and logistics.']])}</div></div>`;case'profile':return `<div class="split">${photo(s.photo,s.caption)}<div class="points"><div class="statement">${s.statement}</div><div class="facts">${s.facts.map(([a,b])=>`<div class="fact"><small>${a}</small><b>${b}</b></div>`).join('')}</div></div></div>`;case'concept':return `<div class="split">${photo(s.photo,s.caption)}<div class="points"><h2>${s.headline}</h2>${points(s.points)}</div></div>`;case'massing':return `<div class="split"><div>${massing(s.hospital)}</div>${points(s.points)}</div>`;case'site':return `<div class="plan-layout">${plan(s.hospital==='tata'?'tata-ground':'mvr-site')}<div class="points">${points(s.points)}<p class="schematic-label">${s.hospital==='tata'?'Building-plan-derived access study. Hollow markers indicate inferred connections.':'Site drawing with analytical routes. Hollow markers indicate inferred connections.'}</p></div></div>`;case'floor':return `<div class="plan-layout">${plan(s.plans[0])}<div class="points">${points(s.points)}${workflow(s.detail)}${s.plans[0].startsWith('mvr')&&details[s.detail]?`<button class="smallbutton" data-photo="details/${details[s.detail]}">Inspect department detail ↗</button>`:''}</div></div>`;case'paired':return `<div class="plan-layout"><div class="paired">${s.plans.map((p,i)=>plan(p,s.planLabels[i])).join('')}</div>${points(s.points)}</div>`;case'stack':return `<div class="split"><div class="stack">${(s.hospital==='tata'?tata:mvr).map((p,i)=>`<div class="stackrow" data-plan="${p}"><b>${esc(PLANS[p].label)}</b><img src="${PLANS[p].path}" alt="${PLANS[p].label} floor plate"><small>Inspect ↗</small></div>`).join('')}</div><div class="points"><h2>Read the hospital vertically.</h2>${points(s.points)}<p class="schematic-label">Exploded analytical stack • heights schematic<br>Click any floor to inspect its zones and circulation.</p></div></div>`;case'network':return `<div class="split"><div>${network()}</div>${points([['Public edge','Reception, OPD and day treatment form the most frequent visitor journey.'],['Controlled care','Surgery and ICU require clear clinical thresholds.'],['Support network','Sterile supply, staff and technical systems connect the departments.']])}</div>`;case'environment':return `<div class="split"><div class="${s.hospital==='tata'?'environment':''}" style="height:100%">${s.hospital==='tata'?`<img class="photo" src="${s.photo}" alt="Tata shaded facade"><img class="section" src="details/tata-section.webp" alt="Source environmental section" data-photo="details/tata-section.webp">`:photo(s.photo,'Architectural rendering · landscape and built form')}</div>${points(s.points)}</div>`;case'evaluation':return `<div class="evaluation">${photo(s.photo,'Interior atrium · supplied study photograph')}<div><h3>Strengths</h3>${points(s.strengths)}</div><div><h3>Limitations</h3>${points(s.limits)}</div></div><p class="lesson">${s.lesson}</p>`;case'comparison':return `<table class="compare"><thead><tr><th>Architectural lens</th><th>Tata Medical Center</th><th>MVR Cancer Centre</th></tr></thead><tbody>${[['Organization','Linked wings around courtyards','Linear spine with connected branches'],['Access','Public front and rear support destinations','Distinct OPD, emergency and service arrivals'],['Clinical zoning','Horizontal clusters with four studied levels','Nine-level stack with specialized upper care'],['Critical relationships','Surgery and critical care on one level','OTs + SICU together; ICU above; CSSD below'],['Healing setting','Courts, shaded edges and sandstone','Planted gaps, bridges, pond and outward views'],['Planning challenge','Walking across wings and bridge junctions','Long ward corridors and mixed core junctions']].map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table><div class="lessons"><p><b>01</b>Make arrival and the next destination obvious.</p><p><b>02</b>Keep critical clinical connections short.</p><p><b>03</b>Use landscape to organize movement and recovery.</p></div>`;default:return''}}
function render(){const s=SLIDES[current];$('#stage').innerHTML=s.type==='cover'?`<article class="slide cover"><div class="covertext"><div class="eyebrow">Architecture Design 7 · Precedent studies</div><h1>Comprehensive<br>Cancer<br>Hospitals</h1><p class="subtitle">Two architectural approaches to care</p><p style="margin-top:35px;font-size:24px;line-height:1.6">Tata Medical Center · Kolkata<br>MVR Cancer Centre · Kozhikode</p><div class="authors"><small>Presentation by</small>Zhyar Peshraw - Bria - Yasr - Akam - Soma - Nma - Layad</div></div><div class="coverimages"><img src="photos/tata-05.webp" alt="Tata Medical Center courtyard"><span>Tata Medical Center</span><img src="photos/mvr-20.webp" alt="MVR Cancer Centre architectural rendering"><span>MVR Cancer Centre · rendering</span></div></article>`:`<article class="slide"><div class="topline"><span>${esc(s.chapter)}</span><span>Architectural case studies</span></div><h1>${esc(s.title)}</h1><p class="subtitle">${esc(s.sub)}</p><div class="body">${body(s)}</div><footer class="footer"><button data-action="sources">Sources: ${s.sources.join(' · ')} ↗</button><span>${String(current+1).padStart(2,'0')} / ${SLIDES.length}</span></footer></article>`;$('#counter').textContent=`${current+1} / ${SLIDES.length}`;$('#progress').style.width=`${(current+1)/SLIDES.length*100}%`;history.replaceState(null,'','#'+(current+1));fit()}
function fit(){const v=$('#viewport');$('#stage').style.transform=`scale(${Math.min(v.clientWidth/1600,v.clientHeight/900)})`}
function go(n){current=Math.max(0,Math.min(SLIDES.length-1,n));render()}
function openModal(title,html){$('#modalTitle').textContent=title;$('#modalbody').innerHTML=html;if(!$('#modal').open)$('#modal').showModal()}
function openPlan(id){const p=PLANS[id];openModal(`${p.hospital==='Tata'?'Tata Medical Center':'MVR Cancer Centre'} · ${p.label}`,`<div class="zoomwrap" data-planarea="${id}"><div class="zoomtools"><button data-zoom="in">+</button><button data-zoom="out">−</button><button data-zoom="reset">Reset</button>${layerbar()}<span>Wheel to zoom · Drag to pan · Hover markers for labels</span></div><div class="zoomview">${planSVG(id)}</div>${legend(id)}<div class="planmeta"><span>${esc(p.source)} · Original raster retained; source resolution limits detail.</span><span>Analytical circulation, not an operational or construction drawing.</span></div></div>`);let scale=1,x=0,y=0,drag=null;const v=$('.zoomview'),svg=v.querySelector('svg'),draw=()=>svg.style.transform=`translate(${x}px,${y}px) scale(${scale})`;v.onwheel=e=>{e.preventDefault();scale=Math.max(1,Math.min(8,scale*(e.deltaY<0?1.13:1/1.13)));draw()};v.onpointerdown=e=>{drag=[e.clientX-x,e.clientY-y];v.setPointerCapture(e.pointerId)};v.onpointermove=e=>{if(drag){x=e.clientX-drag[0];y=e.clientY-drag[1];draw()}};v.onpointerup=()=>drag=null;document.querySelectorAll('[data-zoom]').forEach(b=>b.onclick=()=>{if(b.dataset.zoom==='reset'){scale=1;x=y=0}else scale=Math.max(1,Math.min(8,scale*(b.dataset.zoom==='in'?1.3:1/1.3)));draw()})}
function action(a){const s=SLIDES[current];if(a==='prev')go(current-1);if(a==='next')go(current+1);if(a==='motion'){motion=!motion;document.body.classList.toggle('motion-off',!motion);$('#motion').textContent=motion?'Motion on':'Motion off'}if(a==='fullscreen'){if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>{})}if(a==='overview')openModal('Slide navigator',`<div class="overview">${SLIDES.map((a,i)=>`<button data-goto="${i}" class="${i===current?'active':''}"><small>${String(i+1).padStart(2,'0')} · ${esc(a.chapter)}</small><b>${esc(a.title.replace('\n',' '))}</b><span>${esc(a.sub)}</span></button>`).join('')}</div>`);if(a==='notes')openModal('Presenter notes',`<div class="notes"><div class="eyebrow">Slide ${current+1} · ${s.chapter}</div><h2>${esc(s.title)}</h2><p style="margin-top:25px">${esc(s.notes)}</p><h3>Reading the figures</h3><p>Zoning follows the supplied drawings. Animated routes are architectural interpretations of visible connections. Shared circulation is not proof of dedicated operational separation. Use Source mode to inspect the original drawing colors.</p></div>`);if(a==='sources')openModal('Sources & figure method',`<div class="refs"><p style="font-size:21px;line-height:1.6">All floor plans retain the supplied raster geometry. Colored zoning layers trace source areas; animated routes interpret visible connections. Massing and workflow diagrams are schematic. Source resolution limits very fine room labels. No dimensional, code-compliance or clinical-performance claim is made.</p>${Object.entries(SOURCES).map(([k,v])=>`<article><h3>${k} · ${esc(v.title)}</h3><p>${esc(v.detail)}</p>${v.url?`<a href="${v.url}" target="_blank" rel="noopener">${v.url}</a><small> · external reference; internet required</small>`:`<small>${esc(v.file||'Supplied image set')}</small>`}</article>`).join('')}</div>`);if(a==='gallery')openModal('Source image gallery',`<div class="gallery">${PHOTOS.map(p=>`<figure data-photo="${p.path}"><img src="${p.path}" alt="${esc(p.title||p.label||p.caption||'Supplied source image')}" loading="lazy"><figcaption>${esc(p.title||p.label||p.caption||p.source||p.path.split('/').pop())}</figcaption></figure>`).join('')}${['mvr-blood.webp','mvr-connectivity.webp','mvr-cssd.webp','mvr-emergency.webp','mvr-endoscopy.webp','mvr-icu.webp','mvr-linac-sketch.webp','mvr-nuclear.webp','mvr-opd.webp','mvr-ot.webp','mvr-radiology.webp','mvr-ward.webp','tata-section.webp'].map(f=>`<figure data-photo="details/${f}"><img src="details/${f}" loading="lazy" alt="${f}"><figcaption>${f.replace(/\.(png|jpg|webp)/,'').replaceAll('-',' ')} · source detail</figcaption></figure>`).join('')}${Object.keys(PLANS).filter(k=>k!=='mvr-site').map(k=>`<figure data-plan="${k}"><img src="${PLANS[k].path}" loading="lazy" alt="${k}"><figcaption>${k.replaceAll('-',' ')} · inspect plan</figcaption></figure>`).join('')}</div>`)}
document.addEventListener('click',e=>{const a=e.target.closest('[data-action]'),p=e.target.closest('[data-plan]'),l=e.target.closest('[data-layer]'),g=e.target.closest('[data-goto]'),im=e.target.closest('[data-photo]');if(a)action(a.dataset.action);else if(l){const area=l.closest('[data-planarea]'),key=l.dataset.layer;area.classList.toggle(key==='source'?'source':'no'+key);l.classList.toggle('on')}else if(p)openPlan(p.dataset.plan);else if(g){$('#modal').close();go(+g.dataset.goto)}else if(im)openModal('Source image',`<img class="photomodal" src="${im.dataset.photo}" alt="Supplied architectural or clinical image"><p>Supplied source image · photographs and architectural renderings retain their original content.</p>`)});
$('#closeModal').onclick=()=>$('#modal').close();document.addEventListener('keydown',e=>{if($('#modal').open)return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();go(current+1)}if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();go(current-1)}if(e.key==='Home')go(0);if(e.key==='End')go(SLIDES.length-1);const k={o:'overview',g:'gallery',n:'notes',r:'sources',m:'motion',f:'fullscreen'}[e.key.toLowerCase()];if(k)action(k)});window.addEventListener('resize',fit);document.body.classList.toggle('motion-off',!motion);$('#motion').textContent=motion?'Motion on':'Motion off';render();


/* ===== revision.js ===== */
/* Revision 2: source-native plans, explicit department names and inspected figure crops. */
SOURCES.T5={title:'Tata Medical Center · Spatial & Plan Analysis',file:'Untitled design.pdf',detail:'Additional uploaded analysis. Page 2: site entrances and parking. Pages 5–7: departmental zoning. Page 8 repeats the basement evacuation plan under a Second Floor heading; the original T1 p.16 floor designation is retained. Broad floor zoning follows T2 legends; unreadable individual room labels are not invented.'};
SLIDES[4].title='Four departments, one courtyard campus';SLIDES[4].sub='Source ground plan and courtyard photograph';SLIDES[4].notes='The figure uses the supplied ground-floor plan and its four original department groups, next to the courtyard photograph. The geometry is not replaced by abstract building blocks. Use the numbered names to inspect the actual plan. No building heights are inferred.';
SLIDES[5].sources=['T5','T2'];SLIDES[5].points=[['Main entrance','Front arrival court and drop-off.'],['Second entrance','Radiation-therapy arrival identified in the added study.'],['Emergency entrance','Eastern access to the treatment-side block.'],['Parking','Visitor and staff parking are separately identified.']];SLIDES[5].notes=PLANS['tata-site'].note;
SLIDES[6].sources=['T5','T2'];SLIDES[6].title='Arrival loops and rear access';SLIDES[6].sub='Circulation traced over the supplied site drawing';SLIDES[6].notes=PLANS['tata-site'].note;
SLIDES[7].notes=PLANS['tata-basement'].note;
SLIDES[8].sources=['T2','T5'];SLIDES[9].sources=['T2','T5'];SLIDES[10].sources=['T2','T5'];
SLIDES[11].notes='Source floor plates are indexed by level with their original departmental names. This is a vertical program comparison, not a measured section or a claim that drawings from different sources register exactly.';
SLIDES[12].title='Surgery and critical care';SLIDES[12].sub='A same-level relationship in the source drawing';SLIDES[12].notes='The source second-floor plan places invasive / surgical care in the lower clinical wing and ICU / high dependency / recovery in the upper block. The plan retains the connecting lobby / core between them. The enlarged source crops preserve the original geometry, rather than substituting generic boxes.';
SLIDES[17].title='The spine and the curved branch';SLIDES[17].sub='Source site geometry and architectural rendering';SLIDES[17].notes='Read the source-labelled Block B, curved Block A, OPD, canteen / MEP and service buildings directly on the site drawing. The adjacent supplied rendering communicates the intended built form and landscape. It is not an as-built survey or a measured structural model.';
SLIDES[25].sub='Select a floor to read its named departments';SLIDES[26].sub='Select a floor to compare room types and protected care';
SLIDES[27].notes='All nine documented MVR floor plates are indexed by level, with the named departments and major vertical relationships. This is a program stack, not a measured building section. Click a plate to inspect its source plan.';
const BRIEFS={
 'tata-ground':['Lobby, counselling and outpatient clinics','Combined diagnostic and treatment block','Academic and administrative wing','Upper-left service buildings'],
 'tata-first':['Day treatment and recovery accommodation','Inpatient accommodation in the upper block','Separate academic / administrative wing','Laboratories linked by the upper bridge'],
 'tata-second':['Invasive and surgical services','Intensive care, high-dependency and recovery','Separate academic / administrative wing'],
 'tata-basement':['Laundry, linen sorting and storage','Cleaning, disinfection, packing and sterile supply','Patient / public lifts, service lifts and stairs','Radiotherapy waiting and consultation edge','Planning, mould preparation and dosimetry','Three individually named treatment rooms'],
 'mvr-lower':['Two treatment bunkers with mazes / consoles','Brachytherapy above CT Simulator','Preparation / recovery and mould support','Curved reception and consultation passage','Separate dining, kitchen and utility building','Detached technical / service building'],
 'mvr-ground':['Consultation, pre-assessment and procedures','Triage, examination and observation','Nuclear-medicine scan and preparation rooms','CT, MRI, X-ray and imaging support','Records and pharmacy beside the clinical cores','Public dining beside the eastern approach'],
 'mvr-first':['Specimen testing and laboratory processing','Sterile store, packing and decontamination','Donors, apheresis, serology and TTI lab','ERCP, scope support and prep / recovery','Doctors’ and nurses’ work / lounge areas','Offices, teaching and meeting spaces'],
 'mvr-second':['OT 1–8 around the sterile corridor','Cath lab, sterile store and OT support','Pre-op, post-op and induction bays','Surgical intensive care and isolation','Infusion cubicles and private infusion wards','Separate pediatric waiting and infusion'],
 'mvr-third':['ICU rooms, isolation and nurse station','Pediatric intensive care beside service core','High-dependency care and dialysis','20 standard rooms reported by the study','Two suites at the far right end','Patient / visitor and service lift groups'],
 'mvr-fourth':['Molecular, microbiology and laboratory rooms','Dose administration and isolation rooms','Biomedical equipment store and workshop','27 standard rooms and one suite in the study','Nursing director, staff and clinical support','Central lift and stair groups'],
 'mvr-fifth':['41 standard rooms reported by the study','Single suite at the right end','Three distributed nurse stations','Patient / visitor lobbies and main stair','Service lifts, pantry and staff support','Stairs at both ends of the ward block'],
 'mvr-sixth':['Eight five-bed wards: four male, four female','14 standard rooms in two groups','11 double rooms in the right wing','Distributed nursing, utility and work areas','Central patient / visitor lift group','Service / staff lifts and soiled support'],
 'mvr-seventh':['11 BMT rooms, each with an airlock','Clean utility, sterile store and soiled hold','Airlock, changing and examination spaces','10 deluxe rooms shown in the drawing','Eight standard rooms and two suites','Ordinary inpatient access and lift lobbies'],
 'mvr-site':['Principal outpatient arrival','Separate arrival at the rear of Block B','Service access to canteen / MEP','Entry to the detached service building','Parking area; staff door is not identified','Long inpatient / emergency block'],
 'tata-site':['Front arrival court and drop-off','Radiation-therapy arrival in the added study','Eastern arrival beside the treatment block','Parking along the curved visitor approach','Rear parking group in the added study']
};
Object.entries(BRIEFS).forEach(([id,lines])=>PLANS[id].areas.forEach((a,i)=>a.brief=lines[i]));
const originalBody=body, originalAction=action;
const sheetName=p=>p.hospital==='Tata'?'Tata Medical Center':'MVR Cancer Centre';
function badges(id,compact=false){const p=PLANS[id];return `<div class="department-key ${compact?'compact':''}"><div class="key-title">${compact?'':'Named locations'} <span>${p.areas.length} verified areas</span></div>${p.areas.map(a=>`<button class="dept" data-area="${a.n}" data-id="${id}" title="Inspect ${esc(a.name)}"><span class="dept-no" style="--zone:${a.color}">${a.n}</span><span><b>${esc(a.name)}</b>${compact?'':`<small>${esc(a.brief||a.detail)}</small>`}</span><i>↗</i></button>`).join('')}</div>`}
planSVG=function(id){const p=PLANS[id];return `<svg class="source-plan" viewBox="0 0 1000 ${p.vbHeight}" data-fullbox="0 0 1000 ${p.vbHeight}" role="img" aria-label="${esc(sheetName(p)+' '+p.label+' with named departments')}"><image href="${p.path}" width="1000" height="${p.vbHeight}"/><g class="flows">${p.corridors.map((r,i)=>`<path class="route route-${i}" d="${r.d}" stroke="${FLOWS[r.kind||'shared'][1]}"><title>${esc(r.label)}</title></path>`).join('')}</g><g class="pins">${p.areas.map(a=>`<g class="pin verified-pin" data-area="${a.n}" data-id="${id}" transform="translate(${a.x} ${a.y})"><title>${esc(a.name)}</title><circle class="pin-halo" r="18" fill="${a.color}"/><circle r="12"/><text>${a.n}</text></g>`).join('')}</g></svg>`};
layerbar=function(){return `<div class="layerbar"><button class="on" data-vmode="names">Zoning & names</button><button data-vmode="flows">Circulation</button><button data-vmode="source">Original plan</button><button data-reset="true">Reset view</button></div>`};
legend=function(id){const p=PLANS[id];return `<div class="planmeta v2meta"><span>${p.source}</span><span>${id==='tata-basement'?'Evacuation plan · red fill is not departmental zoning':'Original drawing colors retained'}</span></div>`};
plan=function(id,title=''){const p=PLANS[id];return `<div class="planarea verified-plan" data-planarea="${id}">${title?`<h3>${esc(title)}</h3>`:''}${layerbar()}<div class="focus-heading"><b>${p.label} · complete plan</b><span>Choose a numbered name to inspect its location</span></div><div class="planframe v2-planframe" data-open-plan="${id}">${planSVG(id)}<button class="expand-plan" data-open-plan="${id}">Full-screen plan ↗</button><div class="source-minimap" style="height:${130*p.height/p.width}px"><img src="${p.path}" alt="Whole-floor context"><div></div></div></div><div class="plan-guidance">${p.note?esc(p.note):'Numbered locations use the department names in the source drawing. Click a name for an enlarged source crop.'}</div>${legend(id)}<div class="source-actions"><button data-sheet="${p.sheet}">Read source sheet ↗</button><span class="flow-explainer">Circulation shows visible shared connections; it does not certify exclusive staff or service routes.</span></div></div>`};
function floorLayout(id,flows=false){let html=`<div class="verified-layout">${plan(id)}${badges(id)}</div>`;if(flows)html=html.replace('verified-plan"','verified-plan show-flows"').replace('class="on" data-vmode="names"','data-vmode="names"').replace('data-vmode="flows"','class="on" data-vmode="flows"');return html}
function pairedLayout(s){return `<div class="paired-v2"><div class="floor-tabs">${s.plans.map((id,i)=>`<button data-floor-tab="${id}" class="${i===0?'active':''}"><b>${PLANS[id].label}</b><span>${esc(s.planLabels[i].split(' · ')[1])}</span></button>`).join('')}</div><div id="paired-content">${floorLayout(s.plans[0])}</div></div>`}
function sourceFigure(s){const id=s.hospital==='tata'?'tata-ground':'mvr-site',p=PLANS[id],im=s.hospital==='tata'?'photos/tata-05.webp':'photos/mvr-20.webp';return `<div class="source-figure"><div class="figure-plan"><div class="figure-label">01 / Source ${s.hospital==='tata'?'ground floor':'site plan'}</div><div class="figure-plan-frame" data-open-plan="${id}">${planSVG(id)}</div><div class="figure-key">${p.areas.filter(a=>s.hospital==='tata'||[1,3,4,6].includes(a.n)).map(a=>`<button data-area="${a.n}" data-id="${id}"><strong>${a.n}</strong>${esc(a.name)}</button>`).join('')}</div></div><div class="figure-photo"><div class="figure-label">02 / ${s.hospital==='tata'?'Courtyard photograph':'Architectural rendering'}</div>${photo(im,s.hospital==='tata'?'Courtyard and bridge · supplied photograph':'Connected forms and landscape · supplied rendering')}<h2>${s.hospital==='tata'?'The courtyard connects the wings.':'The landscape sits between connected blocks.'}</h2><p>${s.hospital==='tata'?'The source plan identifies four departmental groups around shared courts and circulation.':'Read the long Block B, the curved lower building, and the detached service / canteen blocks in the source site plan.'}</p></div></div>`}
const floorFunctions={
 'tata-basement':'Laundry · CSSD · Radiotherapy','tata-ground':'OPD · Imaging / radiation · Administration · Support','tata-first':'Day hospital · Inpatient · Laboratories','tata-second':'Surgery · ICU / high dependency / recovery',
 'mvr-lower':'LINAC · Brachytherapy · CT simulation · Canteen','mvr-ground':'OPD · Emergency · Nuclear medicine · Radiology','mvr-first':'Hematology · CSSD · Blood bank · Endoscopy','mvr-second':'OTs · SICU · Infusion / day care','mvr-third':'ICU · PICU · HDU / dialysis · Inpatient rooms','mvr-fourth':'Laboratories · Nuclear medicine · Inpatient rooms','mvr-fifth':'Standard rooms · Suite · Nursing / support','mvr-sixth':'Five-bed wards · Standard rooms · Double rooms','mvr-seventh':'BMT · Deluxe rooms · Standard rooms · Suites'};
function stackV2(s){const ids=(s.hospital==='tata'?tata:mvr).slice().reverse();return `<div class="program-stack ${s.hospital}">${ids.map((id,i)=>`<button class="program-floor" data-open-plan="${id}" style="--delay:${i*60}ms"><span class="floor-level">${PLANS[id].label}</span><img src="${PLANS[id].path}" alt="${PLANS[id].label} source floor plate"><span class="floor-program">${floorFunctions[id]}</span><span class="floor-arrow">Inspect ↗</span></button>`).join('')}</div><p class="stack-method">Vertical program index · original floor plates · no invented storey heights or building volumes</p>`}
function sourceCrop(id,box){const p=PLANS[id];return `<svg viewBox="${box[0]} ${box[1]} ${box[2]-box[0]} ${box[3]-box[1]}" role="img" aria-label="Source plan detail"><image href="${p.path}" width="1000" height="${p.vbHeight}"/></svg>`}
function surgeryFigure(){return `<div class="clinical-relation"><div class="clinical-crop" data-area="1" data-id="tata-second"><div class="figure-label">01 / Invasive Services / Surgical Care</div>${sourceCrop('tata-second',[445,390,745,841])}<p>Long surgical wing · source legend 1</p></div><div class="relation-text"><span class="link-line"></span><h2>A short link between clinical departments</h2><p>The connecting lobby and core sit between surgery and critical care in the second-floor drawing.</p><button data-open-plan="tata-second">Inspect the complete second floor ↗</button><small>Department relationship; operating protocols are not specified by the source.</small></div><div class="clinical-crop" data-area="2" data-id="tata-second"><div class="figure-label">02 / ICU / High Dependency / Recovery</div>${sourceCrop('tata-second',[446,31,747,357])}<p>Connected critical-care block · source legend 2</p></div></div>`}
body=function(s){if(s.type==='floor')return floorLayout(s.plans[0]);if(s.type==='paired')return pairedLayout(s);if(s.type==='site')return floorLayout(s.hospital==='tata'?'tata-site':'mvr-site',s.mode==='routes');if(s.type==='massing')return sourceFigure(s);if(s.type==='stack')return stackV2(s);if(s.type==='network')return surgeryFigure();return originalBody(s)};
let viewTimers=[],viewAnimations=new WeakMap(),tourTimer=null,autoTimer=null;
function stopTour(){clearInterval(tourTimer);tourTimer=null;document.querySelectorAll('[data-tour]').forEach(b=>b.textContent='Guided tour')}
function animateView(svg,target){const from=svg.getAttribute('viewBox').split(/\s+/).map(Number);cancelAnimationFrame(viewAnimations.get(svg));const begin=performance.now();function tick(now){const t=motion?Math.min(1,(now-begin)/650):1,e=1-Math.pow(1-t,3);svg.setAttribute('viewBox',target.map((v,i)=>from[i]+(v-from[i])*e).join(' '));if(t<1)viewAnimations.set(svg,requestAnimationFrame(tick))}viewAnimations.set(svg,requestAnimationFrame(tick))}
function focusArea(container,id,n){const p=PLANS[id],a=p.areas.find(a=>a.n===+n),svg=container.querySelector('.source-plan');if(!a||!svg)return;const box=a.box,pad=12,target=[Math.max(0,box[0]-pad),Math.max(0,box[1]-pad),box[2]-box[0]+pad*2,box[3]-box[1]+pad*2];animateView(svg,target);container.classList.add('is-focused');const h=container.querySelector('.focus-heading');if(h)h.innerHTML=`<b>${a.n} / ${esc(a.name)}</b><span>${esc(a.detail)}</span>`;container.querySelectorAll('.verified-pin').forEach(e=>e.classList.toggle('selected',+e.dataset.area===+n));const scope=container.closest('.verified-layout,.zoom-layout')||container.parentElement;scope.querySelectorAll('.dept').forEach(e=>e.classList.toggle('active',+e.dataset.area===+n));const mini=container.querySelector('.source-minimap div');if(mini){mini.style.left=box[0]/10+'%';mini.style.top=box[1]/p.vbHeight*100+'%';mini.style.width=(box[2]-box[0])/10+'%';mini.style.height=(box[3]-box[1])/p.vbHeight*100+'%'}}
function resetPlan(c){const svg=c.querySelector('.source-plan');if(svg)animateView(svg,svg.dataset.fullbox.split(' ').map(Number));c.classList.remove('is-focused');const p=PLANS[c.dataset.planarea],h=c.querySelector('.focus-heading');if(h)h.innerHTML=`<b>${p.label} · complete plan</b><span>Choose a numbered name to inspect its location</span>`;(c.closest('.verified-layout,.zoom-layout')||c).querySelectorAll('.dept.active').forEach(e=>e.classList.remove('active'))}
function setupPan(c){const v=c.querySelector('.planframe'),svg=c.querySelector('.source-plan');let drag=null;v.addEventListener('wheel',e=>{e.preventDefault();const [x,y,w,h]=svg.getAttribute('viewBox').split(' ').map(Number),f=e.deltaY<0?.85:1/.85;const nw=Math.max(40,Math.min(2000,w*f)),nh=h*nw/w;svg.setAttribute('viewBox',[x+(w-nw)/2,y+(h-nh)/2,nw,nh].join(' '))},{passive:false});v.addEventListener('pointerdown',e=>{if(e.target.closest('button,.pin'))return;drag={x:e.clientX,y:e.clientY,box:svg.getAttribute('viewBox').split(' ').map(Number)};v.setPointerCapture(e.pointerId)});v.addEventListener('pointermove',e=>{if(!drag)return;const r=svg.getBoundingClientRect(),ratio=Math.max(drag.box[2]/r.width,drag.box[3]/r.height);svg.setAttribute('viewBox',[drag.box[0]-(e.clientX-drag.x)*ratio,drag.box[1]-(e.clientY-drag.y)*ratio,drag.box[2],drag.box[3]].join(' '))});v.addEventListener('pointerup',()=>drag=null)}
openPlan=function(id,n){stopTour();const p=PLANS[id];openModal(`${sheetName(p)} · ${p.label}`,`<div class="zoom-layout">${plan(id)}<aside><div class="zoom-buttons"><button data-tour="${id}">Guided tour</button><button data-zoom-v2="in">+</button><button data-zoom-v2="out">−</button></div>${badges(id,true)}<p class="zoom-help">Wheel to zoom · Drag to pan<br>Click a department name to inspect it.<br>Reset view restores the complete plan.</p></aside></div>`);const c=$('#modal [data-planarea]');c.querySelector('[data-open-plan]').removeAttribute('data-open-plan');c.querySelector('.expand-plan').remove();setupPan(c);if(n)focusArea(c,id,n)};
function showSource(path){openModal('Original source sheet',`<div class="sheet-view"><p>Original uploaded study sheet · preserved for checking labels and annotations. Browser zoom or scroll to inspect.</p><img src="${path}" alt="Original uploaded source sheet"></div>`)}
action=function(a){if(a==='notes'){const s=SLIDES[current],id=s.plans?.[0];openModal('Presenter notes',`<div class="notes"><div class="eyebrow">Slide ${current+1} · ${esc(s.chapter)}</div><h2>${esc(s.title)}</h2><p style="margin-top:25px">${esc(s.notes)}</p>${id?`<h3>Source reading</h3><p>${esc(PLANS[id].note||'Use the named department index to inspect each source area.')}</p>`:''}<h3>Figure method</h3><p>The original drawing geometry and colors are retained. Numbered keys transcribe readable department names. Inspection windows enlarge source areas; they are not new departmental boundaries. Circulation overlays follow visible passages. Distinct route colors do not establish a dedicated corridor for every user group.</p></div>`);return}if(a==='sources'){openModal('Sources & drawing audit',`<div class="refs"><h2>Read the drawing before the diagram.</h2><p style="font-size:21px;line-height:1.6;margin-top:20px">This revision preserves original zoning colors and removes the automatic recoloring and generic massing blocks. Department names are checked against original legends or readable room labels. Each plan links to its original study sheet. Source colors can differ between floors; numbered place names are the primary key.</p><article><h3>Resolved conflicts</h3><p>The additional Tata analysis mis-titles the basement evacuation drawing as Second Floor. The original T1 p.16 designation is retained. Its red fills do not indicate departmental zoning. MVR first-floor CSSD, Blood Bank, Hematology and Endoscopy remain distinct. Fourth-floor room labels take priority over the sheet’s stray Cardiac ICU heading.</p></article>${Object.entries(SOURCES).map(([k,v])=>`<article><h3>${k} · ${esc(v.title)}</h3><p>${esc(v.detail)}</p>${v.url?`<a href="${v.url}" target="_blank" rel="noopener">${v.url}</a><small> · optional external reading</small>`:`<small>${esc(v.file||'Supplied image set')}</small>`}</article>`).join('')}</div>`);return}if(a==='overview'){openModal('Explore the presentation',`<div class="overview v2-overview">${SLIDES.map((s,i)=>{const id=s.plans?.[0],im=id?PLANS[id].path:s.photo||((s.hospital||'tata')==='tata'?'photos/tata-05.webp':'photos/mvr-20.webp');return `<button data-goto="${i}" class="${i===current?'active':''}"><img src="${im}" alt=""><small>${String(i+1).padStart(2,'0')} · ${esc(s.chapter)}</small><b>${esc(s.title.replace('\n',' '))}</b></button>`}).join('')}</div>`);return}if(a==='autoplay'){if(autoTimer){clearInterval(autoTimer);autoTimer=null;$('#autoplay').textContent='Auto play'}else{autoTimer=setInterval(()=>{if(!$('#modal').open){if(current===SLIDES.length-1){clearInterval(autoTimer);autoTimer=null;$('#autoplay').textContent='Auto play'}else go(current+1)}},20000);$('#autoplay').textContent='Pause'}return}originalAction(a)};
// Capture figure-specific actions before the original generic photo handlers.
document.addEventListener('click',e=>{const zone=e.target.closest('[data-area]'),op=e.target.closest('[data-open-plan]'),tab=e.target.closest('[data-floor-tab]'),mode=e.target.closest('[data-vmode]'),reset=e.target.closest('[data-reset]'),sheet=e.target.closest('[data-sheet]'),tour=e.target.closest('[data-tour]'),zoom=e.target.closest('[data-zoom-v2]');if(!(zone||op||tab||mode||reset||sheet||tour||zoom))return;e.preventDefault();e.stopImmediatePropagation();if(zone){const id=zone.dataset.id,n=zone.dataset.area,scope=zone.closest('.verified-layout,.zoom-layout'),c=scope?.querySelector('[data-planarea]');if(c)focusArea(c,id,n);else openPlan(id,n)}else if(op)openPlan(op.dataset.openPlan);else if(tab){$('#paired-content').innerHTML=floorLayout(tab.dataset.floorTab);document.querySelectorAll('[data-floor-tab]').forEach(t=>t.classList.toggle('active',t===tab))}else if(mode){const c=mode.closest('[data-planarea]');c.classList.remove('show-flows','show-source');if(mode.dataset.vmode==='flows')c.classList.add('show-flows');if(mode.dataset.vmode==='source')c.classList.add('show-source');c.querySelectorAll('[data-vmode]').forEach(b=>b.classList.toggle('on',b===mode));resetPlan(c)}else if(reset){stopTour();resetPlan(reset.closest('[data-planarea]'))}else if(sheet)showSource(sheet.dataset.sheet);else if(tour){if(tourTimer){stopTour();return}let i=0;const id=tour.dataset.tour,c=$('#modal [data-planarea]'),run=()=>{focusArea(c,id,PLANS[id].areas[i++%PLANS[id].areas.length].n)};run();tour.textContent='Pause tour';tourTimer=setInterval(run,6000)}else if(zoom){const svg=$('#modal .source-plan'),[x,y,w,h]=svg.getAttribute('viewBox').split(' ').map(Number),f=zoom.dataset.zoomV2==='in'?.75:1/.75;animateView(svg,[x+w*(1-f)/2,y+h*(1-f)/2,w*f,h*f])}},true);
$('#modal').addEventListener('close',stopTour);
const ap=document.createElement('button');ap.id='autoplay';ap.dataset.action='autoplay';ap.textContent='Auto play';$('#controls').insertBefore(ap,$('#motion'));
document.body.classList.add('revision-two');render();


