/* ===== analysis.js ===== */
'use strict';
const priorBody=body,priorAction=action,priorRender=render;
const sourceInspectionPlan=plan;
plan=function(id,title=''){let html=sourceInspectionPlan(id,title);const n=SLIDES.findIndex(s=>(s.type==='roles'&&s.id===id)||(s.route&&s.plan===id));return html.replace('<button data-vmode="flows">Circulation</button>',n>=0?`<button data-related-circulation="${n}">Circulation analysis ↗</button>`:'')};
const wrapText=(s,n=37)=>{const lines=[];let line='';String(s).split(' ').forEach(w=>{if((line+' '+w).trim().length>n&&line){lines.push(line);line=w}else line=(line+' '+w).trim()});if(line)lines.push(line);return lines};
const svgText=(x,y,text,cls,max=37,dy=18)=>`<text x="${x}" y="${y}" class="${cls}">${wrapText(text,max).map((l,i)=>`<tspan x="${x}" dy="${i?dy:0}">${esc(l)}</tspan>`).join('')}</text>`;
const roleKey=k=>ROLE_META[k]||[k,'#385a4d'];
let journeyTimer=null;
function stopJourney(){clearInterval(journeyTimer);journeyTimer=null;document.querySelectorAll('[data-journey]').forEach(b=>b.textContent='Animate journeys')}
function plateGeometry(id){const p=PLANS[id],tall=id.startsWith('tata')||id.endsWith('site'),maxW=tall?700:1410,maxH=tall?505:345,scale=Math.min(maxW/1000,maxH/p.vbHeight);return {scale,x:(1468-1000*scale)/2,y:tall?(550-p.vbHeight*scale)/2:100+(350-p.vbHeight*scale)/2,w:1000*scale,h:p.vbHeight*scale,tall}}
function annotatedSVG(id){const p=PLANS[id],a=ANNOTATIONS[id],g=plateGeometry(id);let positions=[];
 if(g.tall){let left=a.map((v,i)=>i).sort((i,j)=>a[i][0]-a[j][0]).slice(0,Math.ceil(a.length/2));let right=a.map((v,i)=>i).filter(i=>!left.includes(i));[left,right].forEach((arr,side)=>{arr.sort((i,j)=>a[i][1]-a[j][1]);arr.forEach((i,j)=>positions[i]={x:side?1138:14,y:23+j*(498/arr.length),side})})}
 else {let ids=a.map((v,i)=>i).sort((i,j)=>a[i][1]-a[j][1]);let top=ids.slice(0,3).sort((i,j)=>a[i][0]-a[j][0]),bottom=ids.slice(3).sort((i,j)=>a[i][0]-a[j][0]);[top,bottom].forEach((arr,side)=>arr.forEach((i,j)=>positions[i]={x:25+j*489,y:side?462:12,side}))}
 const notes=a.map(([x,y,title,detail],i)=>{let q=positions[i],tx=g.x+x*g.scale,ty=g.y+y*g.scale,lx=q.x+(g.tall?(q.side?0:307):200),ly=q.y+(g.tall?38:q.side?-8:71);let d=g.tall?`M${lx} ${ly}L${q.side?g.x+g.w+18:g.x-18} ${ly}L${tx} ${ty}`:`M${lx} ${ly}L${lx} ${q.side?440:99}L${tx} ${ty}`;return `<g class="analysis-note" data-note="${i}" style="--i:${i}" tabindex="0" role="button" aria-label="${esc(title)}"><path class="leader-shadow" d="${d}"/><path class="leader" d="${d}" pathLength="1"/><circle class="anchor-ring" cx="${tx}" cy="${ty}" r="5"/><circle class="anchor-dot" cx="${tx}" cy="${ty}" r="2"/><rect class="callout-bg" x="${q.x-5}" y="${q.y-13}" width="${g.tall?312:440}" height="${g.tall?104:92}" rx="6"/>${svgText(q.x,q.y+7,String(i+1).padStart(2,'0')+' / '+title,'callout-title',g.tall?32:46,21)}${svgText(q.x,q.y+(wrapText(title,g.tall?27:41).length>1?57:35),detail,'callout-detail',g.tall?39:57,19)}</g>`}).join('');
 return `<svg class="annotated-svg" viewBox="0 0 1468 565" role="img" aria-label="${esc(p.label)} with ${a.length} analytical leader notes"><rect x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}" fill="white"/><image href="${p.path}" x="${g.x}" y="${g.y}" width="${g.w}" height="${g.h}"/>${notes}<text class="plate-caption" x="734" y="557" text-anchor="middle">${esc(p.source)} · source geometry and zoning retained</text></svg>`}
function annotatedSlide(s){const p=PLANS[s.id];return `<div class="analysis-plate" data-analysis="${s.id}"><div class="analysis-toolbar"><span class="method-chip">${ANNOTATIONS[s.id].length} plan observations</span><div><button data-build="next">Build analysis <kbd>B</kbd></button><button data-build="all">Show all</button><button data-lines>Leaders on</button><button data-open-plan="${s.id}">Inspect original + zoom ↗</button></div></div>${annotatedSVG(s.id)}<div class="plate-foot"><span>Click a callout to highlight its location · use Build analysis to present one observation at a time</span><button data-sheet="${p.sheet}">Source sheet ↗</button></div></div>`}
function routeControls(kinds,extra=''){return `<div class="route-controls"><button class="selected" data-route-filter="all">All routes</button>${kinds.map(k=>`<button data-route-filter="${k}" style="--route:${roleKey(k)[1]}"><i></i>${esc(roleKey(k)[0])}</button>`).join('')}<button data-journey>Animate journeys</button>${extra}</div>`}
function routePaths(id){return (ROLE_ROUTES[id]||[]).map((r,i)=>{const c=roleKey(r.kind)[1];return `<g class="role-path" data-kind="${r.kind}" style="--route:${c}"><path class="route-under" d="${r.d}"/><path class="role-line" d="${r.d}" stroke="${c}"/><circle class="traveller" r="4" fill="${c}"><animateMotion dur="${8+i}s" repeatCount="indefinite" path="${r.d}"/></circle><title>${esc(r.label)}</title></g>`}).join('')}
function roleSlide(s){const p=PLANS[s.id],kinds=[...new Set(ROLE_ROUTES[s.id].map(r=>r.kind))];return `<div class="route-exhibit">${routeControls(kinds)}<div class="route-grid"><div class="route-figure"><svg class="role-svg" viewBox="0 0 1000 ${p.vbHeight}" role="img" aria-label="${esc(s.title)}"><image href="${p.path}" width="1000" height="${p.vbHeight}"/>${routePaths(s.id)}${p.areas.filter(a=>s.id.endsWith('site')&&a.n<6).map(a=>`<g class="route-label" transform="translate(${a.x} ${a.y})"><circle r="13"/><text y="1">${a.n}</text></g>`).join('')}</svg><button class="inspect-float" data-inspect-figure>Enlarge analysis ↗</button><div class="route-status">All approaches · overlapping segments indicate shared movement</div></div><aside class="reading-notes">${points(s.points)}<p class="evidence-note">${s.id.endsWith('site')?'Entrance positions: team site study. Driveway traces: architectural approach analysis; direction of animation is illustrative.':'Routes follow visible passage relationships. They do not establish exclusive corridors or clinical operating procedures.'}</p></aside></div></div>`}
function teamBubbleSVG(s){const a=TEAM_ASSETS[s.key],r=a.base.rect;const labels={'Inpatient Patient Rooms/Wards':'Inpatient rooms / wards','Daycare Recovery/Treatment':'Day-care treatment / recovery','Linac Bunkers':'LINAC bunkers','Operating Suites/Surgical Theatres':'Operating suites / surgical theatres','Pre-Op and Recovery':'Pre-op / recovery'};return `<svg class="team-svg rebuilt-bubbles" viewBox="0 0 ${a.width} ${a.height}" aria-label="Team bubble diagram with original geometry and clearer labels"><image href="${a.base.path}" x="${r[0]}" y="${r[1]}" width="${r[2]-r[0]}" height="${r[3]-r[1]}" opacity=".2"/><g class="original-relations">${a.vectors.map(v=>`<path d="${v.d}" stroke="${v.stroke}" fill="${v.fill}" stroke-width="${v.w}" fill-opacity="${v.fo}" stroke-opacity="${v.so}"/>`).join('')}</g>${a.bubbles.map((n,i)=>{const t=labels[n.text]||n.text,lines=wrapText(t,Math.max(9,Math.floor(n.rx/3.8))),font=n.rx<43?12:13.5,y=n.y-(lines.length-1)*font*.68;return `<g class="team-bubble-node" tabindex="0" style="--i:${i}"><ellipse cx="${n.x}" cy="${n.y}" rx="${n.rx}" ry="${n.ry}" fill="${n.color}" stroke="#fff" stroke-width="2"/>${lines.map((line,j)=>`<text x="${n.x}" y="${y+j*font*1.36}" text-anchor="middle" dominant-baseline="middle" font-size="${font}" fill="${n.color==='#cda799'?'#3a2922':'#fffaf0'}">${esc(line)}</text>`).join('')}</g>`}).join('')}<g class="bubble-source-key" transform="translate(769 327)"><rect x="-13" y="-22" width="190" height="220" rx="8" fill="#fbfaf6"/>${[['#cda799','Public'],['#726251','Semi-private'],['#642d2d','Private']].map(([c,t],i)=>`<circle cx="0" cy="${i*27}" r="6" fill="${c}"/><text x="16" y="${i*27+4}" font-size="12">${t}</text>`).join('')}<path d="M-4 95h29" stroke="#31483a" stroke-width="1.5"/><text x="33" y="99" font-size="11">Strong relation</text><path d="M-4 125h5 M5 125h5 M14 125h5 M23 125h2" stroke="#31483a" stroke-width="1.7" fill="none"/><text x="33" y="129" font-size="11">Moderate relation</text><path d="M-4 155h1 M1 155h1 M6 155h1 M11 155h1 M16 155h1 M21 155h1" stroke="#31483a" stroke-width="2" stroke-linecap="round" fill="none"/><text x="33" y="159" font-size="11">Weak relation</text></g></svg>`}
function teamSVG(s){const a=TEAM_ASSETS[s.key];if(s.bubble&&a.bubbles)return teamBubbleSVG(s);if(!s.route||!a.base)return `<svg class="team-svg" viewBox="0 0 ${a.width} ${a.height}" role="img" aria-label="${esc(s.title)}"><image href="${a.path}" width="${a.width}" height="${a.height}"/></svg>`;
 const rect=a.base.rect;let crop=[0,0,a.width,a.height];if(s.key==='mvr-circ-01')crop=[0,185,1440,465];if(s.key==='mvr-circ-03')crop=[395,55,1040,390];if(s.key==='mvr-team-23')crop=[0,218,1440,455];
 const grouped={};a.vectors.forEach(v=>(grouped[v.kind]??=[]).push(v));return `<svg class="team-svg traced-svg" viewBox="${crop.join(' ')}" role="img" aria-label="${esc(s.title)} · exact PDF route geometry"><image href="${a.base.path}" x="${rect[0]}" y="${rect[1]}" width="${rect[2]-rect[0]}" height="${rect[3]-rect[1]}" opacity=".5"/>${Object.entries(grouped).map(([kind,vs])=>`<g data-kind="${kind}" class="source-trace-group">${vs.map(v=>`<path d="${v.d}" stroke="${v.stroke}" fill="${v.fill}" stroke-width="${v.w}" fill-opacity="${v.fo}" stroke-opacity="${v.so}"/>`).join('')}</g>`).join('')}${s.key==='mvr-team-23'?`<g class="entry-word"><text x="605" y="264" fill="#a46212">Emergency entry</text><text x="530" y="634" fill="#24765c">Service entry</text><text x="36" y="229" fill="#24765c">Canteen / MEP</text><text x="36" y="245" fill="#24765c">service entry</text><text x="1404" y="233" text-anchor="end" fill="#b6443b">Main / OPD</text><text x="1404" y="249" text-anchor="end" fill="#b6443b">entry</text></g>`:''}</svg>`}
function teamSlide(s){const a=TEAM_ASSETS[s.key],kinds=s.people?(s.key==='mvr-team-23'?['patient','staff','emergency','service']:['patient','staff','service']):['main','secondary','room'];return `<div class="team-exhibit ${s.route?'has-route':''} ${s.bubble?'has-bubbles':''}">${s.route?routeControls(kinds):`<div class="source-strip"><span>${s.bubble?'Our original bubble diagram':s.ot?'Our original OT flow detail':'Our original analysis sheet'}</span><button data-sheet="${a.path}">Open source ↗</button></div>`}<div class="team-grid"><div class="team-figure">${teamSVG(s)}<button class="inspect-float" data-inspect-figure>Enlarge ${s.bubble?'bubble diagram':'analysis'} ↗</button>${s.route?`<div class="route-status">${s.people?'Our source combines staff + service in purple':'Original hierarchy: main → secondary → room entry'}</div>`:''}</div><aside class="reading-notes">${points(s.points)}<div class="evidence-note">${s.bubble?'Original bubble positions and relationship lines retained. Circle size is schematic.':s.route?'Exact vector traces from our PDF. Select a route to isolate it.':'Original supplied analysis preserved; explanatory notes distinguish observations from performance claims.'}<button data-sheet="${a.path}">Original sheet · p.${a.page} ↗</button></div></aside></div></div>`}
function clinicalDetail(s){return `<div class="clinical-detail"><div class="detail-source"><img src="${s.photo}" alt="${esc(s.title)}" data-photo="${s.photo}"><p>Original supplied department detail · click to enlarge</p></div><aside><div class="sequence">${s.sequence.map((n,i)=>`<div style="--i:${i}"><small>0${i+1}</small><b>${esc(n)}</b></div>`).join('')}</div>${points(s.points)}<p class="evidence-note">Sequence shows functional relationships; the original detail supplies room geometry.</p></aside></div>`}
function mvrBubbles(){const nodes=[
 [150,165,76,'OPD / public','Ground','#dba59c'],[425,165,81,'Diagnostics','Ground / first','#c1b689'],[720,165,84,'OT / recovery','Second','#9eb9ab'],[1035,165,79,'Infusion','Second','#c8afc4'],
 [150,400,72,'Radiotherapy','Lower ground','#b9b3a1'],[425,400,72,'CSSD','First','#a8c7c9'],[720,400,79,'ICU / PICU','Third','#a4c0bf'],[1035,400,84,'Inpatient / BMT','Third–seventh','#c7ba9d']];
 const links=[[0,1,'same'],[1,2,'vertical'],[2,3,'same'],[4,0,'vertical'],[5,2,'vertical'],[2,6,'vertical'],[6,7,'vertical'],[1,5,'same']];return `<div class="bubble-layout"><svg class="mvr-bubbles" viewBox="0 0 1210 565" role="img" aria-label="MVR clinical adjacency bubble diagram"><g class="bubble-links">${links.map(([i,j,k])=>`<path class="bubble-link ${k}" d="M${nodes[i][0]} ${nodes[i][1]}L${nodes[j][0]} ${nodes[j][1]}"/>`).join('')}</g>${nodes.map(([x,y,r,title,level,c],i)=>`<g class="bubble-node" transform="translate(${x} ${y})" style="--i:${i}" tabindex="0"><circle class="bubble-halo" r="${r+10}"/><circle r="${r}" fill="${c}"/>${svgText(0,-3,title,'bubble-title',17,24)}<text y="35" class="bubble-level">${level}</text></g>`).join('')}<path d="M55 530h80" stroke="#385f50" stroke-width="3"/><text x="150" y="537" class="bubble-legend">Same-level relationship</text><path d="M490 530h80" stroke="#9e785b" stroke-width="3" stroke-dasharray="8 7"/><text x="585" y="537" class="bubble-legend">Relationship across floors</text></svg><aside><h2>Proximity and vertical dependence.</h2><p>CSSD, surgery and critical care depend on a coordinated vertical sequence.</p><p>OPD and diagnostic functions connect the public front to controlled care.</p><small>New schematic derived from our plans. Position and size do not represent floor geometry or area.</small></aside></div>`}
function comparisonBoard(){return `<div class="board-exhibit"><div class="board-tools"><button class="selected" data-board-view="all">Whole board</button><button data-board-view="setting">Healing + landscape</button><button data-board-view="form">Form + daylight</button><button data-board-view="movement">Movement + separation</button><button data-inspect-figure>Enlarge board ↗</button></div><div class="board-image"><svg class="board-svg" viewBox="0 0 1536 1024" data-fullbox="0 0 1536 1024"><image href="team-analysis/team-comparison.webp" width="1536" height="1024"/></svg></div><p>Team comparison board · conceptual illustrations support the argument; source plans establish locations and circulation geometry.</p></div>`}
function synthesis(){return `<div class="synthesis-grid">${[
 ['01','Make the next destination clear.','Tata’s courts and MVR’s spine both depend on readable junctions. Mark entrances, core lobbies and changes in corridor hierarchy.','tata-ground'],
 ['02','Control the clinical interface.','Study the doorway, airlock, changing room and clean / dirty junction. A colored department boundary alone does not explain circulation.','mvr-second'],
 ['03','Design the experience of movement.','Use daylight, landscape and waiting edges to support orientation. Distinguish the patient journey from staff and supply tasks.','mvr-site']
 ].map(([n,t,p,id])=>`<article><small>${n}</small><div class="synthesis-image" data-open-plan="${id}"><img src="${PLANS[id].path}" alt="${t}"></div><h2>${t}</h2><p>${p}</p></article>`).join('')}</div>`}
body=function(s){if(s.type==='annotated')return annotatedSlide(s);if(s.type==='roles')return roleSlide(s);if(s.type==='team')return teamSlide(s);if(s.type==='clinicaldetail')return clinicalDetail(s);if(s.type==='mvrbubble')return mvrBubbles();if(s.type==='comparisonboard')return comparisonBoard();if(s.type==='synthesis')return synthesis();return priorBody(s)};

function filterRoutes(scope,kind){scope.dataset.filter=kind;scope.querySelectorAll('[data-route-filter]').forEach(b=>b.classList.toggle('selected',b.dataset.routeFilter===kind));scope.querySelectorAll('[data-kind]').forEach(e=>{let own=e.dataset.kind,matches=kind==='all'||kind===own||(own==='staffservice'&&['staff','service'].includes(kind));e.classList.toggle('route-muted',!matches);e.classList.toggle('service-view',own==='staffservice'&&kind==='service')});const status=scope.querySelector('.route-status');if(status)status.textContent=kind==='emergency'&&scope.classList.contains('team-exhibit')?'Emergency entry marker from the team sheet · see the following slide for triage and observation':kind==='all'?(scope.classList.contains('team-exhibit')?'Original source traces · staff and service share the purple category':'All approaches · shared route segments intentionally overlap'):(kind==='staff'||kind==='service')&&scope.querySelector('[data-kind="staffservice"]')?`${roleKey(kind)[0]} · the team source combines staff and service; the same trace is shown`:`${roleKey(kind)[0]} · isolated for reading`;}
function buildAnalysis(mode){const c=$('.analysis-plate');if(!c)return;const ns=[...c.querySelectorAll('.analysis-note')];if(mode==='all'){c.dataset.build='all';ns.forEach(n=>n.classList.remove('not-built','focus-note'));return}let step=c.dataset.build==='all'||!c.dataset.build?0:Number(c.dataset.build)+1;if(step>=ns.length)step=0;c.dataset.build=step;ns.forEach((n,i)=>{n.classList.toggle('not-built',i>step);n.classList.toggle('focus-note',i===step)});}
function inspectFigure(){const src=$('.body .team-svg,.body .role-svg,.body .board-svg');if(!src)return;const s=SLIDES[current];openModal(s.title,`<div class="figure-inspector"><div class="inspector-tools"><button data-figure-zoom="in">Zoom +</button><button data-figure-zoom="out">Zoom −</button><button data-figure-zoom="reset">Reset</button><span>Wheel to zoom · drag to pan</span></div><div class="inspector-canvas">${src.outerHTML}</div></div>`);const svg=$('.inspector-canvas svg');svg.classList.add('inspect-svg');svg.dataset.fullbox=svg.getAttribute('viewBox');let drag=null;svg.addEventListener('wheel',e=>{e.preventDefault();zoomFigure(e.deltaY<0?'in':'out')},{passive:false});svg.addEventListener('pointerdown',e=>{drag={x:e.clientX,y:e.clientY,v:svg.getAttribute('viewBox').split(' ').map(Number)};svg.setPointerCapture(e.pointerId)});svg.addEventListener('pointermove',e=>{if(!drag)return;const r=svg.getBoundingClientRect(),ratio=Math.max(drag.v[2]/r.width,drag.v[3]/r.height);svg.setAttribute('viewBox',[drag.v[0]-(e.clientX-drag.x)*ratio,drag.v[1]-(e.clientY-drag.y)*ratio,drag.v[2],drag.v[3]].join(' '))});svg.addEventListener('pointerup',()=>drag=null);}
function zoomFigure(mode){const svg=$('.inspect-svg');if(!svg)return;if(mode==='reset'){animateView(svg,svg.dataset.fullbox.split(' ').map(Number));return}const [x,y,w,h]=svg.getAttribute('viewBox').split(' ').map(Number),f=mode==='in'?.75:1/.75;animateView(svg,[x+w*(1-f)/2,y+h*(1-f)/2,w*f,h*f])}
render=function(){stopJourney();priorRender();document.body.classList.add('revision-three');const s=SLIDES[current];$('#stage').dataset.slideType=s.type;$('#stage').querySelector('.slide').dataset.chapter=s.chapter;const chip=document.createElement('span');chip.className='chapter-indicator';chip.textContent=`${current+1<3?'Introduction':s.chapter.includes('Tata')?'Tata':s.chapter.includes('MVR')?'MVR':'Comparison'} / ${String(current+1).padStart(2,'0')}`;$('#stage').appendChild(chip);if(!motion)document.querySelectorAll('svg').forEach(svg=>svg.pauseAnimations?.());};
action=function(a){if(a==='sources'){openModal('Source register & analysis method',`<div class="refs"><h2>Our drawings, with traceable analysis.</h2><p class="method-intro">The presentation uses original floor-plan geometry, source zoning and the team’s supplied circulation / bubble diagrams. New leader notes explain spatial relationships. The exact PDF route paths are retained on the dedicated circulation slides.</p><article><h3>Reading the route colors</h3><p>Patient, staff, emergency and service approaches can be isolated on the site drawings. MVR’s team circulation sheets combine staff and service; both filters retain that same source geometry. Tata’s interior sheets describe hallway hierarchy, not user-specific corridors.</p></article><article><h3>Conflicts resolved</h3><p>Tata’s basement image is retained as basement despite the second-floor heading in the added analysis. Its evacuation colors are not zoning. MVR’s repeated first-floor summary table is not used to relocate ground-floor functions. Fourth-floor laboratory labels take priority over the stray Cardiac ICU heading. BMT room count follows the drawing.</p></article>${Object.entries(SOURCES).map(([k,v])=>`<article><h3>${k} · ${esc(v.title)}</h3><p>${esc(v.detail)}</p>${v.url?`<a href="${v.url}" target="_blank" rel="noopener">Optional online source ↗</a>`:`<small>${esc(v.file||'Supplied image set')}</small>`}</article>`).join('')}</div>`);return}if(a==='gallery'){priorAction(a);const gallery=$('#modal .gallery');if(gallery)gallery.insertAdjacentHTML('beforeend',Object.entries(TEAM_ASSETS).map(([k,a])=>`<figure data-sheet="${a.path}"><img loading="lazy" src="${a.path}" alt="${esc(k)}"><figcaption>Team analysis · ${esc(a.source)} · p.${a.page}</figcaption></figure>`).join('')+`<figure data-photo="team-analysis/team-comparison.webp"><img src="team-analysis/team-comparison.webp" alt="Team comparison board"><figcaption>Team comparative analysis</figcaption></figure>`);return}priorAction(a);if(a==='motion')document.querySelectorAll('svg').forEach(svg=>motion?svg.unpauseAnimations?.():svg.pauseAnimations?.());};

document.addEventListener('click',e=>{const b=e.target.closest('button[data-build]'),l=e.target.closest('[data-lines]'),note=e.target.closest('[data-note]'),f=e.target.closest('[data-route-filter]'),j=e.target.closest('[data-journey]'),inspect=e.target.closest('[data-inspect-figure]'),z=e.target.closest('[data-figure-zoom]'),bv=e.target.closest('[data-board-view]');if(!(b||l||note||f||j||inspect||z||bv))return;e.preventDefault();e.stopImmediatePropagation();if(b){stopStudioBuild();buildAnalysis(b.dataset.build);}if(l){const c=l.closest('.analysis-plate');c.classList.toggle('hide-leaders');l.textContent=c.classList.contains('hide-leaders')?'Leaders off':'Leaders on'}if(note){stopStudioBuild();const c=note.closest('.analysis-plate');c.querySelectorAll('.analysis-note').forEach(n=>n.classList.toggle('focus-note',n===note));}if(f){stopJourney();filterRoutes(f.closest('.route-exhibit,.team-exhibit'),f.dataset.routeFilter)}if(j){if(journeyTimer){stopJourney();return}const c=j.closest('.route-exhibit,.team-exhibit'),kinds=[...c.querySelectorAll('[data-route-filter]')].map(b=>b.dataset.routeFilter).filter(k=>k!=='all');let i=0;filterRoutes(c,kinds[0]);j.textContent='Pause journeys';journeyTimer=setInterval(()=>filterRoutes(c,kinds[++i%kinds.length]),4200)}if(inspect)inspectFigure();if(z)zoomFigure(z.dataset.figureZoom);if(bv){const boxes={all:[0,0,1536,1024],setting:[0,180,1536,253],form:[0,425,1536,333],movement:[0,750,1536,274]};animateView($('.board-svg'),boxes[bv.dataset.boardView]);document.querySelectorAll('[data-board-view]').forEach(b=>b.classList.toggle('selected',b===bv))}},true);
document.addEventListener('keydown',e=>{if($('#modal').open)return;if(e.key.toLowerCase()==='b')buildAnalysis('next');if(e.key.toLowerCase()==='j')$('[data-journey]')?.click()});
document.addEventListener('click',e=>{const b=e.target.closest('[data-related-circulation]');if(!b)return;e.preventDefault();e.stopImmediatePropagation();if($('#modal').open)$('#modal').close();go(Number(b.dataset.relatedCirculation))},true);
current=Math.max(0,Math.min(SLIDES.length-1,requestedSlide-1));render();


/* ===== studio.js ===== */
