SLIDES.forEach((s,i)=>{s.title=STUDIO_TITLES[i];if(STUDIO_SUBTITLES[i])s.sub=STUDIO_SUBTITLES[i]});
SLIDES[2].statement='Open courts turn separate wings into a connected clinical campus.';
SLIDES[3].headline='The open space does the organizing.';
