SLIDES[22].headline='Connection without a single deep block.';

function studioChapter(i=current){return STUDIO_CHAPTERS.find(c=>i>=c.start&&i<=c.end)}
function studioThumbnail(s,i){return s.id&&PLANS[s.id]?PLANS[s.id].path:s.key&&TEAM_ASSETS[s.key]?TEAM_ASSETS[s.key].path:s.plans?.[0]?PLANS[s.plans[0]].path:s.photo||(i>=21&&i<=45?'photos/mvr-20.webp':'photos/tata-05.webp')}
function studioCover(){return `<article class="slide cover studio-cover">
 <div class="cover-grid" aria-hidden="true"></div>
 <section class="studio-cover-copy">
  <p class="cover-kicker"><span></span> Architecture Design 7 / Case studies</p>
  <h1><span>Architecture</span><span>of <em>care.</em></span></h1>
  <p class="cover-deck">Comprehensive cancer hospitals<br>Reading the spaces that connect care.</p>
  <div class="cover-cases"><button data-goto="2"><small>01 / KOLKATA</small><b>Tata Medical Center</b><span>Courts & connections ↗</span></button><button data-goto="21"><small>02 / KOZHIKODE</small><b>MVR Cancer Centre</b><span>Spine & landscape ↗</span></button></div>
  <button class="begin-study" data-goto="1">Begin the study <span>→</span></button>
  <div class="authors"><small>Presentation by</small><p>Zhyar Peshraw - Bria - Yasr - Akam - Soma - Nma - Layad</p></div>
 </section>
 <section class="cover-visual">
  <div class="cover-main-image" data-photo="photos/tata-05.webp"><img src="photos/tata-05.webp" alt="Tata Medical Center courtyard and bridge"><div class="cover-image-label"><span>01</span><div><b>The courtyard</b><small>Tata Medical Center · photograph</small></div></div></div>
  <div class="cover-second-image" data-photo="photos/mvr-20.webp"><img src="photos/mvr-20.webp" alt="MVR Cancer Centre architectural rendering"><div class="cover-image-label"><span>02</span><div><b>The clinical spine</b><small>MVR Cancer Centre · rendering</small></div></div></div>
  <div class="cover-stat"><span>02</span><small>Hospitals</small><span>13</span><small>Floor plans</small><span>49</span><small>Slides</small></div>
  <svg class="cover-contour" viewBox="0 0 700 900" aria-hidden="true"><path d="M680 70H545V185H380V365H230V540H55V820"/><path d="M700 96H570V214H408V393H257V570H80V900"/><circle cx="380" cy="365" r="6"/><circle cx="230" cy="540" r="6"/></svg>
 </section></article>`}

let studioBuildTimer=null,studioLastChapter=null,studioLastIndex=null,studioLaser=false,studioCurtainTimer=null;
function stopStudioBuild(){clearInterval(studioBuildTimer);studioBuildTimer=null;document.querySelectorAll('[data-auto-build]').forEach(b=>{b.textContent='Play observations';b.classList.remove('selected')})}
function playStudioBuild(){if(studioBuildTimer){stopStudioBuild();return}const c=$('.analysis-plate');if(!c)return;stopJourney();c.dataset.build='all';buildAnalysis('next');const btn=$('[data-auto-build]');btn.textContent='Pause observations';btn.classList.add('selected');studioBuildTimer=setInterval(()=>{if($('#modal').open)return;const count=c.querySelectorAll('.analysis-note').length;if(+c.dataset.build>=count-1){stopStudioBuild();return}buildAnalysis('next')},3800)}

const studioBaseRender=render;
render=function(){
 stopStudioBuild();
 const chapter=studioChapter(),previousChapter=studioLastChapter,previousIndex=studioLastIndex;
 studioBaseRender();
 document.body.classList.add('studio');
 document.body.style.setProperty('--chapter-accent',chapter.accent);
 const s=SLIDES[current],stage=$('#stage');
 if(s.type==='cover')stage.innerHTML=studioCover();
 const slide=stage.querySelector('.slide');
 slide.dataset.tone=['cover','profile','concept','environment','synthesis'].includes(s.type)?'ink':'paper';
 slide.dataset.direction=previousIndex!==null&&current<previousIndex?'back':'forward';
 stage.dataset.chapterNumber=chapter.number;
 if(s.type!=='cover'){
  slide.querySelector('.topline').innerHTML=`<span class="topline-chapter"><i>${chapter.number}</i>${esc(s.chapter)}</span><span>Architecture of care <b> / </b> ${String(current+1).padStart(2,'0')}</span>`;
  const h=slide.querySelector('h1');h.innerHTML=s.title.split(' ').map((w,i)=>`<span class="title-word" style="--word:${i}">${esc(w)}</span>`).join(' ');
  slide.querySelector('.footer span').innerHTML=`<span class="footer-caption">${s.type==='annotated'?'Source plan + analytical observations':s.route?'Original team circulation geometry':s.bubble?'Original team relationship diagram':'Comparative architectural study'}</span><b>${String(current+1).padStart(2,'0')} <i>/ ${SLIDES.length}</i></b>`;
  if(s.type==='profile'){
   const copy=slide.querySelector('.split>.points');
   copy.insertAdjacentHTML('afterbegin',`<div class="case-number">CASE <b>${chapter.number}</b></div>`);
   slide.querySelector('.photowrap').insertAdjacentHTML('beforeend',`<span class="photo-coordinate">${current===2?'New Town / Kolkata':'Chathamangalam / Kozhikode'}</span>`);
  }
  if(s.type==='annotated'){
   const toolbar=slide.querySelector('.analysis-toolbar>div');
   toolbar.insertAdjacentHTML('afterbegin','<button data-auto-build title="Reveal one observation every 3.8 seconds">Play observations</button>');
   slide.querySelector('[data-build="next"]').firstChild.textContent='Next observation ';
  }
  slide.querySelectorAll('.point').forEach((p,i)=>p.style.setProperty('--point',i));
 }
 updateStudioChrome();
 if(previousChapter!==null&&previousChapter!==chapter.number&&motion){
  const curtain=$('#chapter-curtain');clearTimeout(studioCurtainTimer);curtain.classList.remove('playing');
  curtain.innerHTML=`<small>CHAPTER ${chapter.number}</small><b>${esc(chapter.label)}</b><span></span>`;
  void curtain.offsetWidth;curtain.classList.add('playing');studioCurtainTimer=setTimeout(()=>curtain.classList.remove('playing'),1000);
 }
 studioLastChapter=chapter.number;studioLastIndex=current;fit();
};
function updateStudioChrome(){
 const c=studioChapter();
 document.querySelectorAll('[data-chapter-jump]').forEach(b=>{b.classList.toggle('active',+b.dataset.chapterJump===c.start);b.setAttribute('aria-current',+b.dataset.chapterJump===c.start?'step':'false')});
 $('#chapter-caption').textContent=`${c.short} · ${current-c.start+1} / ${c.end-c.start+1}`;
 $('#chapter-progress-fill').style.width=((current-c.start+1)/(c.end-c.start+1)*100)+'%';
 $('#controls [data-action="prev"]').disabled=current===0;
 $('#controls [data-action="next"]').disabled=current===SLIDES.length-1;
 $('#counter').textContent=String(current+1).padStart(2,'0')+' / '+SLIDES.length;
}

function studioOverview(){
 openModal('Explore the study',`<div class="navigator-toolbar"><label><span>Search slides</span><input id="slide-search" type="search" placeholder="Try: BMT, emergency, courtyard…" autocomplete="off"></label><div class="navigator-filters"><button class="selected" data-nav-filter="all">All 49</button>${STUDIO_CHAPTERS.map(c=>`<button data-nav-filter="${c.number}">${c.short}</button>`).join('')}</div><small id="search-count">49 slides</small></div><div class="overview studio-overview">${SLIDES.map((s,i)=>`<button data-goto="${i}" class="${i===current?'active':''}" data-chapter="${studioChapter(i).number}" data-search="${esc([s.title,s.sub,s.chapter,...(s.points||[]).flat()].join(' ').toLowerCase())}"><div class="navigator-image"><img src="${studioThumbnail(s,i)}" alt="" loading="lazy"><span>${String(i+1).padStart(2,'0')}</span></div><small>${esc(s.chapter)}</small><b>${esc(s.title)}</b></button>`).join('')}</div><p class="empty-search" hidden>No matching slides. Try a department, level or hospital name.</p>`);
 $('#slide-search').addEventListener('input',filterStudioOverview);
 setTimeout(()=>$('#slide-search')?.focus(),60);
}
function filterStudioOverview(){const query=$('#slide-search')?.value.trim().toLowerCase()||'',chapter=$('[data-nav-filter].selected')?.dataset.navFilter||'all';let count=0;document.querySelectorAll('.studio-overview [data-goto]').forEach(b=>{b.hidden=!(b.dataset.search.includes(query)&&(chapter==='all'||b.dataset.chapter===chapter));if(!b.hidden)count++});$('#search-count').textContent=count+' slide'+(count===1?'':'s');$('.empty-search').hidden=count!==0}
function studioHelp(){openModal('Present with confidence',`<div class="studio-help"><div><span class="help-index">01 / MOVE</span><h2>Navigate the story.</h2><p>Use the arrows, keyboard, chapter tabs or searchable slide navigator. Your slide number stays in the address bar.</p><dl><dt>← / → or Space</dt><dd>Previous / next slide</dd><dt>Home / End</dt><dd>First / last slide</dd><dt>O</dt><dd>Search the slide navigator</dd><dt>F</dt><dd>Enter or leave full screen</dd></dl></div><div><span class="help-index">02 / EXPLAIN</span><h2>Reveal the reading.</h2><p>Plan observations can appear one at a time. Select a route category to isolate its geometry, or use a guided journey.</p><dl><dt>B</dt><dd>Build the next plan observation</dd><dt>J</dt><dd>Play / pause route categories</dd><dt>L</dt><dd>Toggle the presentation laser</dd><dt>M</dt><dd>Toggle animation</dd></dl></div><div><span class="help-index">03 / INSPECT</span><h2>Stay close to the source.</h2><p>Enlarge figures, open original plans and inspect named departments. Wheel to zoom; drag to pan. Every source image is included offline.</p><dl><dt>G</dt><dd>Source image gallery</dd><dt>N / R</dt><dd>Presenter notes / source register</dd><dt>Esc</dt><dd>Close a figure or dialog</dd><dt>?</dt><dd>Open this guide</dd></dl></div></div><div class="help-foot">Auto play advances every 20 seconds and pauses while a dialog is open. Motion off also stops automatic observation and route cycles. Slide 2 is a relationship diagram; it has no arrowheads.</div>`)}
const studioBaseAction=action;
action=function(a){
 if(a==='overview'){studioOverview();return}
 if(a==='help'){studioHelp();return}
 if(a==='laser'){studioLaser=!studioLaser;document.body.classList.toggle('laser-on',studioLaser);$('#laser-button').classList.toggle('selected',studioLaser);$('#laser-button').setAttribute('aria-pressed',String(studioLaser));$('#laser-button').textContent=studioLaser?'Laser on':'Laser';if(!studioLaser)$('#laser-dot').classList.remove('visible');return}
 studioBaseAction(a);
 if(a==='motion'&&!motion){stopStudioBuild();stopJourney();stopTour();$('#chapter-curtain').classList.remove('playing')}
};

document.body.insertAdjacentHTML('beforeend',`<div id="studio-chrome"><div class="studio-brand"><span class="brand-mark">ac</span><span>Architecture<br><b>of care.</b></span></div><nav class="chapter-nav" aria-label="Chapters">${STUDIO_CHAPTERS.map(c=>`<button data-chapter-jump="${c.start}" title="${esc(c.label)}"><small>${c.number}</small>${c.short}</button>`).join('')}</nav><div class="chapter-status"><small id="chapter-caption"></small><div id="chapter-progress"><span id="chapter-progress-fill"></span></div></div></div><div id="chapter-curtain" aria-hidden="true"></div><div id="laser-dot" aria-hidden="true"></div>`);
$('#controls').insertAdjacentHTML('beforeend','<button data-action="laser" id="laser-button" title="Presentation laser (L)" aria-pressed="false">Laser</button><button data-action="help" class="help-button" title="Presenter guide (?)">?</button>');
$('#controls [data-action="overview"]').textContent='Explore';
$('#controls [data-action="prev"]').setAttribute('aria-label','Previous slide');
$('#controls [data-action="next"]').setAttribute('aria-label','Next slide');
$('#counter').setAttribute('aria-live','polite');
document.addEventListener('click',e=>{
 const c=e.target.closest('[data-chapter-jump]'),p=e.target.closest('[data-auto-build]'),f=e.target.closest('[data-nav-filter]');
 if(c){go(+c.dataset.chapterJump);return}
 if(p){playStudioBuild();return}
 if(f){document.querySelectorAll('[data-nav-filter]').forEach(b=>b.classList.toggle('selected',b===f));filterStudioOverview()}
});
document.addEventListener('pointermove',e=>{
 const dot=$('#laser-dot'),inside=!!e.target.closest('#stage,#modalbody');
 const laserParent=$('#modal').open?$('#modal'):document.body;if(dot.parentNode!==laserParent)laserParent.appendChild(dot);
 if(studioLaser){dot.style.left=e.clientX+'px';dot.style.top=e.clientY+'px';dot.classList.toggle('visible',inside)}
 if(!motion||SLIDES[current].type!=='cover')return;
 const rect=$('#stage').getBoundingClientRect();$('#stage').style.setProperty('--pointer-x',((e.clientX-rect.left)/rect.width-.5).toFixed(3));$('#stage').style.setProperty('--pointer-y',((e.clientY-rect.top)/rect.height-.5).toFixed(3));
});
document.addEventListener('pointerleave',()=>$('#laser-dot').classList.remove('visible'));
document.addEventListener('keydown',e=>{if($('#modal').open||e.target.matches('input,textarea'))return;if(e.key.toLowerCase()==='l')action('laser');if(e.key==='?')action('help')});
// Stop a guided observation cycle when the presenter takes manual control.
document.addEventListener('click',e=>{if(e.target.closest('button[data-build],[data-note]'))stopStudioBuild()},true);
// Add keyboard activation to the source callouts without changing their geometry.
document.addEventListener('keydown',e=>{const n=e.target.closest('[data-note]');if(n&&['Enter',' '].includes(e.key)){e.preventDefault();e.stopImmediatePropagation();n.dispatchEvent(new MouseEvent('click',{bubbles:true}))}},true);
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopStudioBuild();stopJourney()}});
// Retain a native diagram with no marker-end arrowheads on slide 2.
render();

window.addEventListener('hashchange',()=>{const n=Number(location.hash.slice(1))-1;if(Number.isInteger(n)&&n>=0&&n<SLIDES.length&&n!==current)go(n)});
